values ('fa05e88d-e750-5dad-81e8-df238e186b09', '["vii"]'::jsonb, 'Paragraph G discusses lessons matched to each learner, and some people are cautious about it.', 'Đoạn G bàn về bài học được điều chỉnh cho từng người, và có người còn dè dặt về điều này.', 4227, 4251, null);
values ('3d452018-9854-5335-b24d-47d807bcdee5', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'c2cbfcff-e334-5f8a-a212-5a0a7fab4e70', 5, 'multiple_choice', 'Questions 20–22. Choose the correct letter, A, B, C or D.', null);
values ('39c501ed-706d-5fc1-8798-4af3b7391c4e', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '3d452018-9854-5335-b24d-47d807bcdee5', 1, 20, 'According to the writer, the online courses of ten years ago', '[{"id":"A","text":"were designed mainly for university students."},{"id":"B","text":"were rarely finished by the people who joined them."},{"id":"C","text":"included too many short quizzes."},{"id":"D","text":"were more expensive than classroom courses."}]'::jsonb, 'single', null, null);
values ('39c501ed-706d-5fc1-8798-4af3b7391c4e', '["B"]'::jsonb, 'Completion rates were notoriously low, often below ten per cent.', 'Tỉ lệ hoàn thành rất thấp, thường dưới 10%.', 242, 279, null);
values ('f1dc9f40-cc83-5b8e-9d04-9f8e243439b9', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '3d452018-9854-5335-b24d-47d807bcdee5', 2, 21, 'What did Hermann Ebbinghaus show?', '[{"id":"A","text":"Attention spans are becoming shorter."},{"id":"B","text":"One long study session is the most efficient method."},{"id":"C","text":"New information is lost quickly unless it is met again."},{"id":"D","text":"Short lessons are easier to design."}]'::jsonb, 'single', null, null);
values ('f1dc9f40-cc83-5b8e-9d04-9f8e243439b9', '["C"]'::jsonb, 'He showed that people forget new information quickly unless they meet it again.', 'Ông chỉ ra rằng người ta quên thông tin mới rất nhanh nếu không gặp lại nó.', 961, 1024, null);
values ('f882eb2c-8ebe-5f6c-8b82-a38fba295603', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '3d452018-9854-5335-b24d-47d807bcdee5', 3, 22, 'In the logistics study, the short safety sessions worked best when', '[{"id":"A","text":"they were delivered in a classroom."},{"id":"B","text":"workers chose their own topics."},{"id":"C","text":"supervisors talked about them with their teams."},{"id":"D","text":"they lasted at least half a day."}]'::jsonb, 'single', null, null);
values ('f882eb2c-8ebe-5f6c-8b82-a38fba295603', '["C"]'::jsonb, 'The sessions were most effective when supervisors discussed the content with their teams afterwards.', 'Các buổi ngắn hiệu quả nhất khi quản lý thảo luận lại nội dung với nhóm sau đó.', 3187, 3268, null);
values ('975ee630-79e6-5740-a22d-68f5e6098ffa', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'c2cbfcff-e334-5f8a-a212-5a0a7fab4e70', 6, 'multiple_choice_multi', 'Questions 23–24. Choose TWO letters, A–E.', null);
values ('59f3a536-8970-5fc3-a376-8bd0181c1270', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '975ee630-79e6-5740-a22d-68f5e6098ffa', 1, 23, 'Which TWO kinds of learning does the writer say microlearning suits well?', '[{"id":"A","text":"learning vocabulary"},{"id":"B","text":"writing a persuasive essay"},{"id":"C","text":"learning the steps to use new software"},{"id":"D","text":"analysing a difficult text"},{"id":"E","text":"taking part in group discussions"}]'::jsonb, 'multiple', 2, null);
values ('59f3a536-8970-5fc3-a376-8bd0181c1270', '["A","C"]'::jsonb, 'Microlearning works well for vocabulary and for clearly defined procedures such as using new software. Essays and difficult texts are given as examples of what it does not suit.', 'Microlearning hợp với từ vựng và các quy trình rõ ràng như cách dùng phần mềm mới. Viết luận và phân tích văn bản khó là ví dụ cho điều nó không hợp.', 2033, 2110, null);
values ('eee5b17b-0d2c-5642-9e81-28c7099c5276', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'c2cbfcff-e334-5f8a-a212-5a0a7fab4e70', 7, 'summary_completion', 'Questions 25–26. Complete the summary. Write ONE WORD ONLY from the passage for each answer.', null);
values ('64297418-109b-5c71-b4e8-1ee1da10f17a', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'eee5b17b-0d2c-5642-9e81-28c7099c5276', 1, 25, 'Features such as daily streaks and reminders help studying to become a ______.', null, 'text', null, 1);
values ('64297418-109b-5c71-b4e8-1ee1da10f17a', '["habit"]'::jsonb, 'Reminders encourage learners to return each day until studying becomes a habit.', 'Lời nhắc khuyến khích người học quay lại mỗi ngày cho đến khi việc học thành thói quen (habit).', 1711, 1741, null);
values ('315fe78e-c4ba-5729-9413-989ed430407d', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'eee5b17b-0d2c-5642-9e81-28c7099c5276', 2, 26, 'A learner who keeps a streak by doing the easiest lesson may feel ______ while making little real progress.', null, 'text', null, 1);
values ('315fe78e-c4ba-5729-9413-989ed430407d', '["productive"]'::jsonb, 'Such a learner may feel productive while making very little real progress.', 'Người học như vậy có thể cảm thấy mình năng suất (productive) dù tiến bộ rất ít.', 1907, 1965, null);
values ('8db699f5-c4f4-5597-910f-2d20dc8fff57', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '009424c3-57d4-5dd0-b38c-fe1e72ad3e5a', 8, 'yes_no_not_given', 'Questions 27–31. Do the following statements agree with the views of the writer in Reading Passage 3? Choose YES, NO or NOT GIVEN.', '[{"id":"YES","text":"YES"},{"id":"NO","text":"NO"},{"id":"NOT_GIVEN","text":"NOT GIVEN"}]'::jsonb);
values ('e1e21bb4-1692-5170-a558-3f711acc858c', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '8db699f5-c4f4-5597-910f-2d20dc8fff57', 1, 27, 'People who live in cities are much more likely to feel lonely than people in the countryside.', null, 'single', null, null);
values ('e1e21bb4-1692-5170-a558-3f711acc858c', '["NO"]'::jsonb, 'The writer reports that rural people feel lonely about as often as city people, sometimes more often.', 'Tác giả dẫn khảo sát cho thấy người ở nông thôn cô đơn ngang, thậm chí hơn, người thành phố.', 365, 442, null);
values ('f30e0f85-9762-53f7-be75-c0c9cac12c12', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '8db699f5-c4f4-5597-910f-2d20dc8fff57', 2, 28, 'The belief that cities isolate people is partly based on a romantic view of village life.', null, 'single', null, null);
values ('f30e0f85-9762-53f7-be75-c0c9cac12c12', '["YES"]'::jsonb, 'The writer says the idea says more about our nostalgia for village life.', 'Tác giả cho rằng quan niệm này phản ánh nỗi hoài niệm về cuộc sống làng quê nhiều hơn.', 692, 738, null);
values ('3da7fde0-3542-5b9e-bdf1-2ffe8e100ecf', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '8db699f5-c4f4-5597-910f-2d20dc8fff57', 3, 29, 'Brief conversations with strangers are more valuable than time spent with close friends.', null, 'single', null, null);
values ('3da7fde0-3542-5b9e-bdf1-2ffe8e100ecf', '["NOT_GIVEN"]'::jsonb, 'The writer says brief interactions help, but never compares their value with time spent with close friends.', 'Tác giả nói các cuộc trò chuyện ngắn có ích, nhưng không so sánh chúng với thời gian bên bạn thân.', null, null, null);
values ('28fe2ff4-e354-503c-a2e9-04241fc2b473', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '8db699f5-c4f4-5597-910f-2d20dc8fff57', 4, 30, 'Planning projects that aim to increase social contact are a sensible approach.', null, 'single', null, null);
values ('28fe2ff4-e354-503c-a2e9-04241fc2b473', '["YES"]'::jsonb, 'Although it is too early to measure their effect, the writer believes the direction is the right one.', 'Dù còn sớm để đo hiệu quả, tác giả tin rằng đây là hướng đi đúng.', 2780, 2820, null);
values ('ffdbd437-b0fc-5ee5-96cd-f6aac61a40c3', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '8db699f5-c4f4-5597-910f-2d20dc8fff57', 5, 31, 'Online friendships can fully replace local contact for people who are at risk of loneliness.', null, 'single', null, null);
values ('ffdbd437-b0fc-5ee5-96cd-f6aac61a40c3', '["NO"]'::jsonb, 'The writer finds this argument unconvincing and says online contact does not help those most at risk.', 'Tác giả thấy lập luận này không thuyết phục và cho rằng liên lạc online không giúp được nhóm dễ cô đơn nhất.', 3133, 3158, null);
values ('eabcb95a-5b4a-535c-9a45-726f93b55c84', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '009424c3-57d4-5dd0-b38c-fe1e72ad3e5a', 9, 'matching_information', 'Questions 32–35. Reading Passage 3 has six paragraphs, A–F. Which paragraph contains the following information?', '[{"id":"A","text":"Paragraph A"},{"id":"B","text":"Paragraph B"},{"id":"C","text":"Paragraph C"},{"id":"D","text":"Paragraph D"},{"id":"E","text":"Paragraph E"},{"id":"F","text":"Paragraph F"}]'::jsonb);
values ('982cfe95-6216-5a9c-b905-0236a7c1a362', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'eabcb95a-5b4a-535c-9a45-726f93b55c84', 1, 32, 'an example of a city reducing traffic to create public spaces', null, 'single', null, null);
values ('982cfe95-6216-5a9c-b905-0236a7c1a362', '["D"]'::jsonb, 'Paragraph D describes Barcelona closing streets to through traffic and creating small squares.', 'Đoạn D kể Barcelona cấm xe chạy xuyên qua một số phố và biến giao lộ thành quảng trường nhỏ.', 2320, 2363, null);
values ('9f01e40b-2eb6-59ef-911d-fc0934782ecf', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'eabcb95a-5b4a-535c-9a45-726f93b55c84', 2, 33, 'a description of two types of social relationship', null, 'single', null, null);
values ('9f01e40b-2eb6-59ef-911d-fc0934782ecf', '["B"]'::jsonb, 'Paragraph B explains the difference between strong ties and weak ties.', 'Đoạn B giải thích sự khác nhau giữa quan hệ thân thiết (strong ties) và quan hệ xã giao (weak ties).', 948, 992, null);
values ('b28f6570-2ce5-56a0-9d6e-692dac72d074', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'eabcb95a-5b4a-535c-9a45-726f93b55c84', 3, 34, 'a reference to factors other than design that affect loneliness', null, 'single', null, null);
values ('b28f6570-2ce5-56a0-9d6e-692dac72d074', '["F"]'::jsonb, 'Paragraph F mentions personal circumstances, health and income.', 'Đoạn F nhắc đến hoàn cảnh cá nhân, sức khoẻ và thu nhập.', 3744, 3807, null);
values ('11c9c3cc-2e90-56cf-95dc-d7a509231d28', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'eabcb95a-5b4a-535c-9a45-726f93b55c84', 4, 35, 'a contrast between two kinds of neighbourhood layout', null, 'single', null, null);
values ('11c9c3cc-2e90-56cf-95dc-d7a509231d28', '["C"]'::jsonb, 'Paragraph C contrasts a street with small shops and benches with a district built around fast roads.', 'Đoạn C so sánh con phố có cửa hàng nhỏ, ghế ngồi với khu vực xây quanh đường cao tốc và bãi đỗ xe.', 1644, 1719, null);
values ('f7cfc71c-793f-5b28-8b8a-ace7d830403c', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', '009424c3-57d4-5dd0-b38c-fe1e72ad3e5a', 10, 'summary_completion', 'Questions 36–40. Complete the summary. Write ONE WORD ONLY from the passage for each answer.', null);
values ('6c071231-fb97-5fcb-9502-067538af7315', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'f7cfc71c-793f-5b28-8b8a-ace7d830403c', 1, 36, 'Sandstrom found that brief everyday interactions gave people a greater sense of ______.', null, 'text', null, 1);
values ('6c071231-fb97-5fcb-9502-067538af7315', '["belonging"]'::jsonb, 'People with more brief interactions reported a greater sense of belonging.', 'Người có nhiều tương tác ngắn hằng ngày cảm thấy gắn bó (belonging) hơn.', 1240, 1277, null);
values ('78358589-4b59-502c-8358-3b5048c796c3', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'f7cfc71c-793f-5b28-8b8a-ace7d830403c', 2, 37, 'Streets with small shops, benches and wide pavements give people reasons to ______.', null, 'text', null, 1);
values ('78358589-4b59-502c-8358-3b5048c796c3', '["linger"]'::jsonb, 'Such streets give people reasons to linger, that is, to stay a little longer.', 'Những con phố như vậy cho người ta lý do nán lại (linger) lâu hơn.', 1568, 1598, null);
values ('ff87c253-056e-5a8f-95b2-d7c33db1bc99', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'f7cfc71c-793f-5b28-8b8a-ace7d830403c', 3, 38, 'In tall towers, residents may share a ______ but have no natural place for conversation.', null, 'text', null, 1);
values ('ff87c253-056e-5a8f-95b2-d7c33db1bc99', '["lift"]'::jsonb, 'Residents may share a lift but rarely a space where conversation feels natural.', 'Cư dân có thể đi chung thang máy (lift) nhưng hiếm có chỗ để trò chuyện tự nhiên.', 1874, 1900, null);
values ('1398dfa4-533f-5a6b-8119-b706d8635078', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'f7cfc71c-793f-5b28-8b8a-ace7d830403c', 4, 39, 'In Barcelona''s scheme, junctions were turned into small ______ with seating and trees.', null, 'text', null, 1);
values ('1398dfa4-533f-5a6b-8119-b706d8635078', '["squares"]'::jsonb, 'The superblocks scheme turned junctions into small squares.', 'Dự án superblocks biến các giao lộ thành những quảng trường nhỏ (squares).', 2368, 2403, null);
values ('63e0490f-72e5-564a-bb18-8447b85c223b', 'a30965b1-dea3-5fd1-b974-8f1c9d3e9c27', 'f7cfc71c-793f-5b28-8b8a-ace7d830403c', 5, 40, 'People most at risk of loneliness include older residents living alone and ______ with no local connections yet.', null, 'text', null, 1);
values ('63e0490f-72e5-564a-bb18-8447b85c223b', '["newcomers"]'::jsonb, 'Newcomers who have not yet formed local connections are named as being at risk.', 'Người mới chuyển đến (newcomers) chưa có mối quan hệ nào ở địa phương là nhóm dễ cô đơn.', 3446, 3501, null);

-- reading-rooftop-gardens (published, v1)
values ('f7452056-ef2c-57b1-8361-2b57400b350f', 'practice_set', 'reading-rooftop-gardens', 'Rooftop gardens in growing cities', 'A short Academic-style passage about green roofs, with five common Reading question types.', 'B1', array['environment', 'cities']::text[], 'ai_assisted', 'published', 1);
values ('f7452056-ef2c-57b1-8361-2b57400b350f', 'reading', 'practice', 1200);
values ('4f37a364-066a-5480-9a48-506111468137', 'f7452056-ef2c-57b1-8361-2b57400b350f', 1, 'Rooftop gardens in growing cities', 'A  Across many fast-growing cities, flat roofs are among the least used spaces. They collect heat in summer, shed rainwater too quickly during storms and are rarely visited by anyone except maintenance workers. Over the past two decades, however, a growing number of building owners have begun to cover these surfaces with soil and plants.

B  The most frequently cited benefit is temperature control. A layer of vegetation shades the roof and releases moisture into the air, so the building beneath it stays cooler. Researchers in several Asian cities have measured roof surfaces that were more than twenty degrees cooler than nearby bare concrete on hot afternoons. Lower roof temperatures also reduce the energy needed for air conditioning on the top floors.

C  Green roofs also help with water. Instead of rushing straight into drains, rain is absorbed by the soil and released slowly over several hours. In neighbourhoods where old drainage systems flood after heavy storms, this delay can make a noticeable difference. Some of the water evaporates, while the rest reaches the drains after the peak of the storm has passed.

D  Not every roof is suitable. Soil becomes extremely heavy when it is wet, and older buildings may need structural reinforcement before any planting begins. Installation costs are therefore higher than for a conventional roof, and owners must also budget for regular maintenance, including weeding and the repair of waterproof layers.

E  City governments have tried different ways of encouraging the idea. Some offer tax reductions to owners who install green roofs, while others have made them compulsory on large new commercial buildings. Supporters argue that the long-term savings on energy and flood damage justify the public cost, although critics point out that the benefits are hard to measure for individual buildings.');
values ('6492a480-3be8-5fe9-9504-755ac5a70330', 'f7452056-ef2c-57b1-8361-2b57400b350f', '4f37a364-066a-5480-9a48-506111468137', 1, 'matching_headings', 'The passage has five paragraphs, A–E. Choose the correct heading for paragraphs B–D from the list of headings.', '[{"id":"i","text":"The financial and physical limits of rooftop planting"},{"id":"ii","text":"Slowing the flow of rainwater"},{"id":"iii","text":"A cooler building in hot weather"},{"id":"iv","text":"Why residents prefer rooftop parks"},{"id":"v","text":"Choosing plants for a dry climate"}]'::jsonb);
values ('661ea383-2bc1-5584-b952-edb88bb80c0a', 'f7452056-ef2c-57b1-8361-2b57400b350f', '6492a480-3be8-5fe9-9504-755ac5a70330', 1, 1, 'Paragraph B', null, 'single', null, null);
values ('661ea383-2bc1-5584-b952-edb88bb80c0a', '["iii"]'::jsonb, 'Paragraph B is about temperature: vegetation shades the roof and keeps the building cooler.', 'Đoạn B nói về nhiệt độ: lớp cây che bóng cho mái và giúp tòa nhà mát hơn.', 344, 401, null);
values ('4d8c2903-edf6-5004-8ef1-33402c46521c', 'f7452056-ef2c-57b1-8361-2b57400b350f', '6492a480-3be8-5fe9-9504-755ac5a70330', 2, 2, 'Paragraph C', null, 'single', null, null);
values ('4d8c2903-edf6-5004-8ef1-33402c46521c', '["ii"]'::jsonb, 'Paragraph C explains that soil absorbs rain and releases it slowly, so water reaches drains later.', 'Đoạn C giải thích đất hấp thụ nước mưa và thải ra từ từ, nên nước xuống cống chậm hơn.', 841, 908, null);
values ('3f1242bb-267c-51d5-91a9-81ba0900c676', 'f7452056-ef2c-57b1-8361-2b57400b350f', '6492a480-3be8-5fe9-9504-755ac5a70330', 3, 3, 'Paragraph D', null, 'single', null, null);
values ('3f1242bb-267c-51d5-91a9-81ba0900c676', '["i"]'::jsonb, 'Paragraph D lists the limits: heavy wet soil, reinforcement for older buildings and higher costs.', 'Đoạn D nêu các hạn chế: đất ướt rất nặng, nhà cũ cần gia cố và chi phí cao hơn.', 1134, 1161, null);
values ('6cbefb78-e910-5458-b1b1-f92716a55dda', 'f7452056-ef2c-57b1-8361-2b57400b350f', '4f37a364-066a-5480-9a48-506111468137', 2, 'true_false_not_given', 'Do the following statements agree with the information in the passage? Choose TRUE, FALSE or NOT GIVEN.', '[{"id":"TRUE","text":"TRUE"},{"id":"FALSE","text":"FALSE"},{"id":"NOT_GIVEN","text":"NOT GIVEN"}]'::jsonb);
values ('4baa505b-335d-51fe-a9ff-731f5a497c8c', 'f7452056-ef2c-57b1-8361-2b57400b350f', '6cbefb78-e910-5458-b1b1-f92716a55dda', 1, 4, 'Flat roofs in growing cities are often visited by members of the public.', null, 'single', null, null);
values ('4baa505b-335d-51fe-a9ff-731f5a497c8c', '["FALSE"]'::jsonb, 'The passage says flat roofs are rarely visited by anyone except maintenance workers, which contradicts the statement.', 'Bài đọc nói mái bằng hiếm khi có ai lên ngoài thợ bảo trì, trái với nhận định.', 154, 209, null);
values ('ff514aac-64a2-548f-875d-c204e22a8cd5', 'f7452056-ef2c-57b1-8361-2b57400b350f', '6cbefb78-e910-5458-b1b1-f92716a55dda', 2, 5, 'Green roofs were first introduced in Asian cities.', null, 'single', null, null);
values ('ff514aac-64a2-548f-875d-c204e22a8cd5', '["NOT_GIVEN"]'::jsonb, 'Asian cities are mentioned only as places where temperatures were measured. The passage does not say where green roofs began.', 'Các thành phố châu Á chỉ được nhắc đến là nơi đo nhiệt độ. Bài không nói mái xanh bắt nguồn từ đâu.', null, null, null);
values ('e530b78e-bc30-57a2-9bd6-6aa06bab57ee', 'f7452056-ef2c-57b1-8361-2b57400b350f', '6cbefb78-e910-5458-b1b1-f92716a55dda', 3, 6, 'Some cities require green roofs on certain new buildings.', null, 'single', null, null);
values ('e530b78e-bc30-57a2-9bd6-6aa06bab57ee', '["TRUE"]'::jsonb, 'Some governments have made green roofs compulsory on large new commercial buildings.', 'Một số chính quyền đã bắt buộc mái xanh với các tòa nhà thương mại lớn xây mới.', 1606, 1672, null);
values ('2dc59e59-2363-5bbe-8bb7-44f76d33e420', 'f7452056-ef2c-57b1-8361-2b57400b350f', '4f37a364-066a-5480-9a48-506111468137', 3, 'sentence_completion', 'Complete the sentences. Write NO MORE THAN TWO WORDS from the passage for each answer.', null);
values ('6488eb93-8b94-5a88-9a85-25412174230d', 'f7452056-ef2c-57b1-8361-2b57400b350f', '2dc59e59-2363-5bbe-8bb7-44f76d33e420', 1, 7, 'Vegetation keeps a building cooler by providing shade and releasing ______ into the air.', null, 'text', null, 2);
values ('6488eb93-8b94-5a88-9a85-25412174230d', '["moisture"]'::jsonb, 'The passage says vegetation releases moisture into the air.', 'Bài đọc nói lớp cây thải hơi ẩm (moisture) vào không khí.', 444, 474, null);
values ('d2290b3e-239f-5659-8cbe-671279a89c25', 'f7452056-ef2c-57b1-8361-2b57400b350f', '2dc59e59-2363-5bbe-8bb7-44f76d33e420', 2, 8, 'Before planting, older buildings may need ______.', null, 'text', null, 2);
values ('d2290b3e-239f-5659-8cbe-671279a89c25', '["structural reinforcement","reinforcement"]'::jsonb, 'Older buildings may need structural reinforcement before any planting begins.', 'Nhà cũ có thể cần gia cố kết cấu (structural reinforcement) trước khi trồng cây.', 1211, 1260, null);
values ('6500c6ec-e8e3-56ab-b3a5-d05c5ab70d8a', 'f7452056-ef2c-57b1-8361-2b57400b350f', '4f37a364-066a-5480-9a48-506111468137', 4, 'multiple_choice_multi', 'Choose TWO letters, A–E.', null);
values ('618f06c1-f1af-5f16-a73f-3f7ebfa063bb', 'f7452056-ef2c-57b1-8361-2b57400b350f', '6500c6ec-e8e3-56ab-b3a5-d05c5ab70d8a', 1, 9, 'Which TWO ongoing costs of green roofs does the writer mention?', '[{"id":"A","text":"insurance for the building"},{"id":"B","text":"regular weeding"},{"id":"C","text":"replacing all windows"},{"id":"D","text":"repairing waterproof layers"},{"id":"E","text":"training maintenance staff"}]'::jsonb, 'multiple', 2, null);
values ('618f06c1-f1af-5f16-a73f-3f7ebfa063bb', '["B","D"]'::jsonb, 'Maintenance includes weeding and the repair of waterproof layers. The other costs are not mentioned.', 'Chi phí bảo trì gồm làm cỏ và sửa lớp chống thấm. Các chi phí khác không được nhắc đến.', 1412, 1465, null);
values ('ebf0f8de-ce22-58fc-ae12-4d80e81dde97', 'f7452056-ef2c-57b1-8361-2b57400b350f', '4f37a364-066a-5480-9a48-506111468137', 5, 'multiple_choice', 'Choose the correct letter, A, B, C or D.', null);
values ('bf7f4bc7-bfa0-5620-af97-4d972b8a2fd3', 'f7452056-ef2c-57b1-8361-2b57400b350f', 'ebf0f8de-ce22-58fc-ae12-4d80e81dde97', 1, 11, 'What do critics say about green roofs?', '[{"id":"A","text":"They use too much water."},{"id":"B","text":"Their benefits are difficult to measure for single buildings."},{"id":"C","text":"They are too expensive for governments."},{"id":"D","text":"They make buildings too heavy."}]'::jsonb, 'single', null, null);
values ('bf7f4bc7-bfa0-5620-af97-4d972b8a2fd3', '["B"]'::jsonb, 'Critics point out that the benefits are hard to measure for individual buildings.', 'Những người phản đối cho rằng lợi ích khó đo lường với từng tòa nhà riêng lẻ.', 1802, 1859, null);

values ('b81c553e-b9ef-54a9-802f-3be73500e769', 'academic', 'academic', 'adjective', '/ˌækəˈdemɪk/', 'connected with studying and thinking, rather than practical skills', '(thuộc) học thuật', '[{"en":"Academic success is not the only goal of education.","vi":"Thành tích học tập không phải mục tiêu duy nhất của giáo dục.","cloze":"Academic"},{"en":"Some children are less academic but very good with their hands.","vi":"Có những bạn nhỏ không giỏi học thuật lắm nhưng rất khéo tay.","cloze":"academic"}]'::jsonb, '["academic performance","academic year","academic writing"]'::jsonb, '[{"wrong":"He is very academy.","right":"He is very academic.","whyEn":"Academy is a noun (a school). Academic is the adjective.","whyVi":"Academy là danh từ (học viện); tính từ là academic."}]'::jsonb, 'B2', array['education']::text[]);

values ('44a3c26b-8cbd-5fe5-9c45-31925f4de93c', 'access', 'access', 'noun', '/ˈækses/', 'the right or chance to use or reach something', 'quyền hoặc khả năng tiếp cận, sử dụng', '[{"en":"Rural schools often have poor internet access.","vi":"Trường ở nông thôn thường có kết nối internet kém.","cloze":"access"},{"en":"Everyone should have equal access to education.","vi":"Ai cũng nên có cơ hội tiếp cận giáo dục như nhau.","cloze":"access"}]'::jsonb, '["access to","internet access","equal access"]'::jsonb, '[{"wrong":"Students have access the internet.","right":"Students have access to the internet.","whyEn":"The noun access needs to: access to something.","whyVi":"Danh từ access cần \"to\": have access to something."}]'::jsonb, 'B1', array['technology', 'education']::text[]);

values ('4774f3e3-6c35-5db0-bb5e-b1ecd879f951', 'artificial', 'artificial', 'adjective', '/ˌɑːtɪˈfɪʃl/', 'made by people, not happening naturally', 'nhân tạo: do con người tạo ra, không có sẵn trong tự nhiên', '[{"en":"Many offices rely on artificial light for most of the day.","vi":"Nhiều văn phòng dùng ánh sáng nhân tạo gần như cả ngày.","cloze":"artificial"},{"en":"Some sports stadiums now use artificial grass instead of real turf.","vi":"Một số sân vận động hiện dùng cỏ nhân tạo thay cho cỏ thật.","cloze":"artificial"}]'::jsonb, '["artificial light","artificial intelligence","artificial ingredients"]'::jsonb, '[{"wrong":"The lake is artificial made.","right":"The lake is artificial. / The lake is man-made.","whyEn":"Artificial already means ''made by people'', so do not add ''made''.","whyVi":"Artificial đã có nghĩa là ''do con người làm ra'', nên không thêm ''made'' phía sau."}]'::jsonb, 'B1', array['science', 'technology']::text[]);

values ('06e9e114-c304-5416-9eec-86021d738e5e', 'assess', 'assess', 'verb', '/əˈses/', 'to judge how good, big or important something is', 'đánh giá (mức độ, chất lượng, năng lực)', '[{"en":"Teachers assess students through projects as well as exams.","vi":"Giáo viên đánh giá học sinh qua cả dự án lẫn bài thi.","cloze":"assess"},{"en":"It is hard to assess creativity with a written test.","vi":"Rất khó đánh giá sự sáng tạo bằng một bài kiểm tra viết.","cloze":"assess"}]'::jsonb, '["assess students","assess the impact","carefully assess"]'::jsonb, '[{"wrong":"Teachers assess about students'' work.","right":"Teachers assess students'' work.","whyEn":"Assess takes a direct object, with no preposition.","whyVi":"Assess đi thẳng với tân ngữ, không cần \"about\"."}]'::jsonb, 'B2', array['education']::text[]);

values ('8c1f0e92-5f34-5275-8d6c-79abb0bfa352', 'automate', 'automate', 'verb', '/ˈɔːtəmeɪt/', 'to make a process work by machines instead of people', 'tự động hoá', '[{"en":"Many factories automate simple, repetitive tasks.","vi":"Nhiều nhà máy tự động hoá những việc đơn giản, lặp đi lặp lại.","cloze":"automate"},{"en":"If we automate checkout, what happens to cashiers?","vi":"Nếu tự động hoá quầy thanh toán, những người thu ngân sẽ ra sao?","cloze":"automate"}]'::jsonb, '["automate a process","automate tasks","fully automated"]'::jsonb, '[{"wrong":"Robots will automatic many jobs.","right":"Robots will automate many jobs.","whyEn":"Automatic is an adjective; the verb is automate.","whyVi":"Automatic là tính từ; động từ là automate."}]'::jsonb, 'B2', array['technology', 'work']::text[]);

values ('8289875c-53fb-593b-9a84-52fcebc5809b', 'balanced', 'balanced', 'adjective', '/ˈbælənst/', '(of a diet) with the right amounts of different kinds of food', 'cân bằng (chế độ ăn đủ các nhóm chất)', '[{"en":"A balanced diet includes fruit, vegetables and protein.","vi":"Một chế độ ăn cân bằng gồm trái cây, rau và chất đạm.","cloze":"balanced"},{"en":"It is hard to eat a balanced meal when you are busy.","vi":"Khi bận rộn thì khó ăn một bữa cân bằng.","cloze":"balanced"}]'::jsonb, '["balanced diet","balanced meal","well-balanced"]'::jsonb, '[{"wrong":"You should eat a balance diet.","right":"You should eat a balanced diet.","whyEn":"Before diet, use the adjective balanced (with -ed).","whyVi":"Trước diet phải là tính từ balanced (có -ed)."}]'::jsonb, 'B1', array['health']::text[]);

values ('1a768e7c-42ff-5a1c-a481-9d44b3da62b6', 'biodiversity', 'biodiversity', 'noun', '/ˌbaɪəʊdaɪˈvɜːsəti/', 'the number and variety of plants and animals in an area', 'đa dạng sinh học', '[{"en":"Coral reefs have very high biodiversity.","vi":"Rạn san hô có mức đa dạng sinh học rất cao.","cloze":"biodiversity"},{"en":"Pesticides are a serious threat to biodiversity.","vi":"Thuốc trừ sâu là mối đe doạ nghiêm trọng với đa dạng sinh học.","cloze":"biodiversity"}]'::jsonb, '["loss of biodiversity","protect biodiversity","rich biodiversity"]'::jsonb, '[{"wrong":"There are many biodiversities here.","right":"This area has rich biodiversity.","whyEn":"Biodiversity is uncountable; describe it as rich or high.","whyVi":"Biodiversity không đếm được; hãy nói \"rich/high biodiversity\"."}]'::jsonb, 'B2', array['environment', 'science']::text[]);

values ('484e2026-bf24-5001-9f1a-5865248fce2e', 'breakthrough', 'breakthrough', 'noun', '/ˈbreɪkθruː/', 'an important new discovery or success after a long effort', 'bước đột phá', '[{"en":"Scientists have made a breakthrough in battery technology.","vi":"Các nhà khoa học đã tạo ra bước đột phá trong công nghệ pin.","cloze":"breakthrough"},{"en":"The internet was a breakthrough for distance learning.","vi":"Internet là bước đột phá cho việc học từ xa.","cloze":"breakthrough"}]'::jsonb, '["make a breakthrough","a major breakthrough","scientific breakthrough"]'::jsonb, '[{"wrong":"Scientists did a breakthrough.","right":"Scientists made a breakthrough.","whyEn":"The natural verb is make (or achieve) a breakthrough.","whyVi":"Đi với breakthrough là make (hoặc achieve), không dùng do."}]'::jsonb, 'B2', array['technology', 'science']::text[]);

values ('612827f2-f4a2-5a30-8788-07c15b2b7581', 'chronic', 'chronic', 'adjective', '/ˈkrɒnɪk/', '(of an illness or problem) lasting a long time', 'mãn tính, kéo dài', '[{"en":"Diabetes is a chronic disease that needs daily care.","vi":"Tiểu đường là bệnh mãn tính cần chăm sóc hằng ngày.","cloze":"chronic"},{"en":"Many older people live with chronic pain.","vi":"Nhiều người cao tuổi sống chung với cơn đau mãn tính.","cloze":"chronic"}]'::jsonb, '["chronic disease","chronic pain","chronic stress"]'::jsonb, '[{"wrong":"I have a chronic cold since yesterday.","right":"I have had a bad cold since yesterday.","whyEn":"Chronic means lasting months or years, not one day.","whyVi":"Chronic là kéo dài hàng tháng, hàng năm; cảm từ hôm qua thì chưa \"mãn tính\" đâu."}]'::jsonb, 'B2', array['health']::text[]);

values ('338ef67b-1234-5697-9cce-cbb4862f61c2', 'cliche', 'cliché', 'noun', '/ˈkliːʃeɪ/', 'an idea or phrase used so often that it is no longer original or interesting', 'lối nói sáo rỗng, ý tưởng cũ mòn vì bị dùng quá nhiều', '[{"en":"It is a cliché, but practice really does make perfect.","vi":"Nghe thì sáo, nhưng luyện tập thật sự giúp ta giỏi lên.","cloze":"cliché"},{"en":"Examiners prefer clear ideas to clichés in an essay.","vi":"Giám khảo thích ý tưởng rõ ràng hơn những câu sáo rỗng trong bài luận.","cloze":"clichés"}]'::jsonb, '["an old cliché","become a cliché","avoid clichés"]'::jsonb, '[]'::jsonb, 'C1', array['culture', 'media']::text[]);

values ('70cbda4b-4d6e-58fd-95ab-499185b99cb7', 'compulsory', 'compulsory', 'adjective', '/kəmˈpʌlsəri/', 'required by a rule or law; you must do it', 'bắt buộc (theo quy định hoặc luật)', '[{"en":"In many countries, school is compulsory until the age of sixteen.","vi":"Ở nhiều nước, đi học là bắt buộc đến 16 tuổi.","cloze":"compulsory"},{"en":"Should sport be a compulsory subject at university?","vi":"Thể thao có nên là môn bắt buộc ở đại học không?","cloze":"compulsory"}]'::jsonb, '["compulsory education","compulsory subject","make something compulsory"]'::jsonb, '[{"wrong":"It is compulsory for students wear uniforms.","right":"It is compulsory for students to wear uniforms.","whyEn":"The pattern is \"compulsory for someone to do something\".","whyVi":"Cấu trúc là \"compulsory for sb to do sth\", đừng quên \"to\"."}]'::jsonb, 'B2', array['education']::text[]);

values ('1d5ec4ba-810d-5c74-9a7e-554747c9e3b3', 'conserve', 'conserve', 'verb', '/kənˈsɜːv/', 'to protect something or use less of it so it lasts', 'bảo tồn; tiết kiệm (để dùng được lâu)', '[{"en":"We can conserve water by taking shorter showers.","vi":"Chúng ta có thể tiết kiệm nước bằng cách tắm nhanh hơn.","cloze":"conserve"},{"en":"National parks help conserve wildlife.","vi":"Vườn quốc gia giúp bảo tồn động vật hoang dã.","cloze":"conserve"}]'::jsonb, '["conserve energy","conserve water","conserve natural resources"]'::jsonb, '[{"wrong":"We should conservate energy.","right":"We should conserve energy.","whyEn":"The verb is conserve. Conservation is the noun.","whyVi":"Động từ là conserve; \"conservate\" không tồn tại. Danh từ là conservation."}]'::jsonb, 'B2', array['environment']::text[]);

values ('e89636f1-338d-5783-b386-5a8f06b27c4f', 'conventional', 'conventional', 'adjective', '/kənˈvenʃənl/', 'of the usual or traditional type', 'thông thường, truyền thống, kiểu phổ biến xưa nay', '[{"en":"Electric cars are cheaper to run than conventional cars.","vi":"Xe điện tốn ít chi phí vận hành hơn xe thông thường.","cloze":"conventional"},{"en":"Online classes are replacing conventional lectures in some universities.","vi":"Lớp học trực tuyến đang thay thế bài giảng truyền thống ở một số trường đại học.","cloze":"conventional"}]'::jsonb, '["conventional methods","conventional wisdom","conventional energy"]'::jsonb, '[]'::jsonb, 'B2', array['society', 'technology']::text[]);

values ('90f15611-368b-522b-8eff-a74ef5de8c92', 'curriculum', 'curriculum', 'noun', '/kəˈrɪkjələm/', 'all the subjects a school or course teaches', 'chương trình học: toàn bộ các môn mà trường hoặc khoá học dạy', '[{"en":"Many people think coding should be part of the school curriculum.","vi":"Nhiều người cho rằng lập trình nên có trong chương trình học ở trường.","cloze":"curriculum"},{"en":"The new curriculum gives students more time for practical projects.","vi":"Chương trình mới cho học sinh nhiều thời gian hơn cho các dự án thực hành.","cloze":"curriculum"}]'::jsonb, '["school curriculum","national curriculum","on the curriculum"]'::jsonb, '[{"wrong":"The school has many curriculums.","right":"The school has a broad curriculum.","whyEn":"Curriculum usually means the whole programme, so we rarely count it.","whyVi":"Curriculum thường chỉ cả chương trình, nên hiếm khi đếm \"nhiều curriculum\"."}]'::jsonb, 'B1', array['education']::text[]);

values ('0a49322a-21af-565a-8d3d-66f5eba8bdc2', 'deforestation', 'deforestation', 'noun', '/ˌdiːˌfɒrɪˈsteɪʃn/', 'cutting down large areas of forest', 'nạn phá rừng', '[{"en":"Deforestation destroys the homes of many animals.","vi":"Nạn phá rừng phá huỷ nơi ở của nhiều loài động vật.","cloze":"Deforestation"},{"en":"Farming is one of the main causes of deforestation.","vi":"Trồng trọt là một trong những nguyên nhân chính của nạn phá rừng.","cloze":"deforestation"}]'::jsonb, '["tackle deforestation","large-scale deforestation","the causes of deforestation"]'::jsonb, '[{"wrong":"The deforestations are increasing.","right":"Deforestation is increasing.","whyEn":"Deforestation is uncountable.","whyVi":"Deforestation không đếm được, không thêm -s."}]'::jsonb, 'B2', array['environment']::text[]);

values ('7aae0fd3-f4a1-5565-863b-f593441128e3', 'device', 'device', 'noun', '/dɪˈvaɪs/', 'a machine or tool made for a special purpose, such as a phone', 'thiết bị', '[{"en":"Children now spend hours a day on electronic devices.","vi":"Trẻ em giờ dành hàng giờ mỗi ngày cho thiết bị điện tử.","cloze":"devices"},{"en":"This small device tracks your heart rate.","vi":"Thiết bị nhỏ này theo dõi nhịp tim của bạn.","cloze":"device"}]'::jsonb, '["electronic devices","mobile device","smart device"]'::jsonb, '[{"wrong":"Can you device a plan?","right":"Can you devise a plan?","whyEn":"Device (with c) is the noun. Devise (with s) is the verb meaning to plan.","whyVi":"Device (chữ c) là danh từ \"thiết bị\"; devise (chữ s) là động từ \"nghĩ ra\". Một chữ cái, hai thế giới!"}]'::jsonb, 'B1', array['technology']::text[]);

values ('aee11586-7864-50cc-a574-6304531ed7d1', 'digital', 'digital', 'adjective', '/ˈdɪdʒɪtl/', 'using computers and the internet; stored as numbers', 'kỹ thuật số', '[{"en":"Older people may struggle with digital services.","vi":"Người lớn tuổi có thể gặp khó với các dịch vụ kỹ thuật số.","cloze":"digital"},{"en":"Libraries now lend digital books as well as paper ones.","vi":"Thư viện giờ cho mượn cả sách điện tử lẫn sách giấy.","cloze":"digital"}]'::jsonb, '["digital technology","digital age","digital skills"]'::jsonb, '[{"wrong":"We live in a digitals world.","right":"We live in a digital world.","whyEn":"Adjectives never take a plural -s in English.","whyVi":"Tính từ tiếng Anh không bao giờ thêm -s số nhiều."}]'::jsonb, 'B1', array['technology']::text[]);

values ('6b01639a-2a9c-50d4-846a-6c65c156543b', 'discipline', 'discipline', 'noun', '/ˈdɪsəplɪn/', 'control of behaviour, often through rules; the ability to keep working', 'kỷ luật; tính tự giác', '[{"en":"Online learning needs a lot of self-discipline.","vi":"Học trực tuyến đòi hỏi rất nhiều tính tự giác.","cloze":"discipline"},{"en":"Strict discipline in schools does not always improve results.","vi":"Kỷ luật nghiêm khắc ở trường không phải lúc nào cũng cải thiện kết quả.","cloze":"discipline"}]'::jsonb, '["self-discipline","strict discipline","maintain discipline"]'::jsonb, '[{"wrong":"Students need a discipline.","right":"Students need discipline.","whyEn":"In this meaning discipline is uncountable: no \"a\".","whyVi":"Với nghĩa \"kỷ luật\", discipline không đếm được nên không dùng \"a\"."}]'::jsonb, 'B2', array['education']::text[]);

values ('8b8013e0-2c24-5065-96e5-9f37b154e47c', 'drainage', 'drainage', 'noun', '/ˈdreɪnɪdʒ/', 'the system of pipes and channels that carries away water', 'hệ thống thoát nước: ống, rãnh dẫn nước đi', '[{"en":"Poor drainage causes streets to flood after heavy rain.","vi":"Hệ thống thoát nước kém khiến đường phố ngập sau mưa lớn.","cloze":"drainage"},{"en":"The city spent millions on a new drainage system.","vi":"Thành phố chi hàng triệu cho một hệ thống thoát nước mới.","cloze":"drainage"}]'::jsonb, '["drainage system","poor drainage","drainage pipes"]'::jsonb, '[]'::jsonb, 'B2', array['cities', 'environment']::text[]);

values ('ca16ab99-602e-59f9-952c-020fb3fbf01e', 'drought', 'drought', 'noun', '/draʊt/', 'a long period with little or no rain', 'hạn hán', '[{"en":"The drought destroyed most of the rice harvest.","vi":"Đợt hạn hán đã phá huỷ phần lớn vụ lúa.","cloze":"drought"},{"en":"Climate change makes severe droughts more common.","vi":"Biến đổi khí hậu khiến hạn hán nghiêm trọng xảy ra thường xuyên hơn.","cloze":"droughts"}]'::jsonb, '["severe drought","suffer from drought","a long drought"]'::jsonb, '[{"wrong":"The weather is very drought.","right":"The weather is very dry.","whyEn":"Drought is a noun. To describe weather, use the adjective dry.","whyVi":"Drought là danh từ; muốn tả thời tiết khô hạn thì dùng tính từ dry."}]'::jsonb, 'B2', array['environment']::text[]);

values ('cff0ad60-d8b4-500c-a29e-f0185c770939', 'dweller', 'dweller', 'noun', '/ˈdwelə(r)/', 'a person who lives in a particular place', 'cư dân: người sống ở một nơi cụ thể (city dweller = người sống ở thành phố)', '[{"en":"Most city dwellers live within walking distance of a bus stop.","vi":"Phần lớn cư dân thành phố sống gần một trạm xe buýt, đi bộ là tới.","cloze":"dwellers"},{"en":"A cave dweller in the story finally sees the sun.","vi":"Một người sống trong hang trong câu chuyện cuối cùng cũng được thấy mặt trời.","cloze":"dweller"}]'::jsonb, '["city dwellers","urban dwellers","apartment dwellers"]'::jsonb, '[]'::jsonb, 'C1', array['cities', 'society']::text[]);

values ('afd6d1ca-f2a4-51af-b3dc-d48818d72a49', 'emission', 'emission', 'noun', '/iˈmɪʃn/', 'gas or other substance sent into the air', 'khí thải, sự phát thải', '[{"en":"Electric buses can cut carbon emissions in big cities.","vi":"Xe buýt điện có thể cắt giảm khí thải carbon ở các thành phố lớn.","cloze":"emissions"},{"en":"The factory was fined for its high emission of toxic gas.","vi":"Nhà máy bị phạt vì thải ra quá nhiều khí độc.","cloze":"emission"}]'::jsonb, '["carbon emissions","reduce emissions","greenhouse gas emissions"]'::jsonb, '[{"wrong":"Cars release a lot of emission.","right":"Cars produce a lot of emissions.","whyEn":"When we talk about gases from cars and factories, emissions is usually plural.","whyVi":"Nói về khí thải từ xe, nhà máy thì thường dùng số nhiều: emissions."}]'::jsonb, 'B2', array['environment']::text[]);

values ('1a4726ed-0dbe-57d4-9fe1-0eeac1909cb0', 'encounter', 'encounter', 'noun', '/ɪnˈkaʊntə(r)/', 'a meeting, especially one that is not planned', 'cuộc gặp gỡ, nhất là gặp tình cờ, không hẹn trước', '[{"en":"A chance encounter at the library led to a lifelong friendship.","vi":"Một cuộc gặp tình cờ ở thư viện đã mở ra một tình bạn trọn đời.","cloze":"encounter"},{"en":"Small daily encounters with neighbours can improve your mood.","vi":"Những lần gặp hàng xóm nho nhỏ mỗi ngày có thể làm bạn vui hơn.","cloze":"encounters"}]'::jsonb, '["a chance encounter","a brief encounter","everyday encounters"]'::jsonb, '[]'::jsonb, 'B2', array['society', 'cities']::text[]);

values ('7b725174-fed1-5e34-909e-560f8446bc4e', 'enthusiastic', 'enthusiastic', 'adjective', '/ɪnˌθjuːziˈæstɪk/', 'showing a lot of interest and excitement about something', 'nhiệt tình, hăng hái, rất hứng thú với điều gì đó', '[{"en":"The students were enthusiastic about the new science club.","vi":"Học sinh rất hào hứng với câu lạc bộ khoa học mới.","cloze":"enthusiastic"},{"en":"Young people are often the most enthusiastic users of new apps.","vi":"Người trẻ thường là những người dùng ứng dụng mới nhiệt tình nhất.","cloze":"enthusiastic"}]'::jsonb, '["enthusiastic about","enthusiastic support","an enthusiastic welcome"]'::jsonb, '[{"wrong":"She is enthusiastic for learning Japanese.","right":"She is enthusiastic about learning Japanese.","whyEn":"The usual preposition after enthusiastic is about.","whyVi":"Giới từ thường đi sau enthusiastic là about."}]'::jsonb, 'B1', array['work', 'education']::text[]);

values ('b87504c2-6f7c-56e4-bc90-cf65f5de327e', 'evaporate', 'evaporate', 'verb', '/ɪˈvæpəreɪt/', '(of a liquid) to change into gas and disappear', 'bay hơi: chất lỏng chuyển thành hơi và biến mất', '[{"en":"In hot weather, water in the pond evaporates quickly.","vi":"Khi trời nóng, nước trong ao bay hơi rất nhanh.","cloze":"evaporates"},{"en":"Leave the paint to dry until the water has evaporated.","vi":"Để sơn khô cho đến khi nước đã bay hơi hết.","cloze":"evaporated"}]'::jsonb, '["evaporate quickly","water evaporates","evaporate into the air"]'::jsonb, '[]'::jsonb, 'B2', array['science', 'environment']::text[]);

values ('a114c495-4459-58b9-8928-5e9d7de8cdaf', 'excessive', 'excessive', 'adjective', '/ɪkˈsesɪv/', 'much more than is needed or reasonable', 'quá mức, nhiều hơn mức cần thiết hoặc hợp lý', '[{"en":"Excessive screen time can make it harder to sleep.","vi":"Dùng màn hình quá nhiều có thể khiến khó ngủ hơn.","cloze":"Excessive"},{"en":"Many people think the new parking fees are excessive.","vi":"Nhiều người cho rằng phí gửi xe mới quá cao.","cloze":"excessive"}]'::jsonb, '["excessive use","excessive amounts","excessive noise"]'::jsonb, '[{"wrong":"He drinks excessive coffee.","right":"He drinks an excessive amount of coffee. / He drinks too much coffee.","whyEn":"Excessive usually describes an amount, a level or a use, not the thing itself.","whyVi":"Excessive thường đi với lượng, mức độ hoặc việc sử dụng, không đứng ngay trước bản thân đồ vật."}]'::jsonb, 'B2', array['environment', 'health']::text[]);

values ('d9284ebf-5b0c-574d-94d4-31b7fed421e2', 'fragment', 'fragment', 'noun', '/ˈfræɡmənt/', 'a small piece or part of something larger', 'mảnh, mẩu nhỏ: một phần nhỏ tách ra từ cái lớn hơn', '[{"en":"Archaeologists found fragments of pottery near the river.","vi":"Các nhà khảo cổ tìm thấy những mảnh gốm gần con sông.","cloze":"fragments"},{"en":"I only heard a fragment of their conversation.","vi":"Tôi chỉ nghe được một mẩu cuộc trò chuyện của họ.","cloze":"fragment"}]'::jsonb, '["small fragments","fragments of glass","a fragment of a conversation"]'::jsonb, '[]'::jsonb, 'B2', array['science', 'education']::text[]);

values ('94110d13-c1cd-52ae-b439-b0a689c01493', 'gadget', 'gadget', 'noun', '/ˈɡædʒɪt/', 'a small, clever machine or tool', 'đồ công nghệ nhỏ, món đồ tiện ích', '[{"en":"My uncle buys every new kitchen gadget he sees.","vi":"Chú tôi thấy món đồ bếp công nghệ nào mới cũng mua.","cloze":"gadget"},{"en":"Smartwatches are popular gadgets among teenagers.","vi":"Đồng hồ thông minh là món đồ công nghệ được thiếu niên ưa chuộng.","cloze":"gadgets"}]'::jsonb, '["the latest gadget","electronic gadgets","kitchen gadget"]'::jsonb, '[{"wrong":"A fridge is a gadget.","right":"A phone charger is a handy gadget.","whyEn":"Gadgets are small; a fridge is an appliance.","whyVi":"Gadget là đồ nhỏ gọn; tủ lạnh to thế thì gọi là appliance."}]'::jsonb, 'B1', array['technology']::text[]);

values ('2b0fed4f-b880-5403-8789-bb2999a1188a', 'graduate-verb', 'graduate', 'verb', '/ˈɡrædʒueɪt/', 'to finish a university degree (or school, in American English)', 'tốt nghiệp', '[{"en":"Many students graduate with large debts.","vi":"Nhiều sinh viên tốt nghiệp với khoản nợ lớn.","cloze":"graduate"},{"en":"After they graduate, some go straight into work.","vi":"Sau khi tốt nghiệp, một số người đi làm ngay.","cloze":"graduate"}]'::jsonb, '["graduate from university","graduate with a degree","graduate in law"]'::jsonb, '[{"wrong":"I graduated Hanoi University.","right":"I graduated from Hanoi University.","whyEn":"In British English we graduate from a place.","whyVi":"Tốt nghiệp \"từ\" trường nào thì nhớ thêm \"from\" nhé."}]'::jsonb, 'B1', array['education']::text[]);

values ('44f200ca-1b4f-51ad-b540-9ad29066e912', 'habitat', 'habitat', 'noun', '/ˈhæbɪtæt/', 'the natural home of a plant or animal', 'môi trường sống tự nhiên (của động, thực vật)', '[{"en":"Pandas are losing their habitat as forests disappear.","vi":"Gấu trúc đang mất dần môi trường sống khi rừng biến mất.","cloze":"habitat"},{"en":"Wetlands are an important habitat for birds.","vi":"Đất ngập nước là môi trường sống quan trọng của các loài chim.","cloze":"habitat"}]'::jsonb, '["natural habitat","habitat loss","destroy a habitat"]'::jsonb, '[{"wrong":"People''s habitat is the city.","right":"Wild animals'' habitat is the forest.","whyEn":"Habitat is normally used for plants and animals, not for people.","whyVi":"Habitat thường dùng cho động thực vật; với người thì dùng home hoặc living environment."}]'::jsonb, 'B1', array['environment']::text[]);

values ('a98e5b6f-cf48-577e-8e9c-0d355042ee7c', 'illuminated', 'illuminated', 'adjective', '/ɪˈluːmɪneɪtɪd/', 'lit up, especially with electric lights', 'được chiếu sáng, thắp sáng (thường bằng đèn điện)', '[{"en":"The old bridge looks beautiful when it is illuminated at night.","vi":"Cây cầu cũ trông rất đẹp khi được thắp sáng vào ban đêm.","cloze":"illuminated"},{"en":"Illuminated signs make the shopping street visible from far away.","vi":"Biển hiệu phát sáng giúp con phố mua sắm dễ thấy từ xa.","cloze":"Illuminated"}]'::jsonb, '["illuminated signs","brightly illuminated","illuminated buildings"]'::jsonb, '[]'::jsonb, 'B2', array['cities']::text[]);

values ('7a83a918-cada-5314-9a4b-17f48639fa21', 'inevitably', 'inevitably', 'adverb', '/ɪnˈevɪtəbli/', 'in a way that cannot be avoided or prevented', 'chắc chắn, không thể tránh khỏi', '[{"en":"As cities grow, traffic inevitably increases.","vi":"Khi thành phố lớn lên, giao thông chắc chắn sẽ tăng.","cloze":"inevitably"},{"en":"Inevitably, some students found the test too long.","vi":"Không tránh khỏi việc một số học sinh thấy bài thi quá dài.","cloze":"Inevitably"}]'::jsonb, '["almost inevitably","inevitably lead to","inevitably involve"]'::jsonb, '[]'::jsonb, 'B2', array['society']::text[]);

values ('74d27983-dee2-5746-8cfc-d0fdbc5d4499', 'innovation', 'innovation', 'noun', '/ˌɪnəˈveɪʃn/', 'a new idea, method or product, or the act of creating one', 'sự đổi mới; ý tưởng, sản phẩm mới', '[{"en":"Small start-ups are often the source of innovation.","vi":"Các công ty khởi nghiệp nhỏ thường là nguồn của sự đổi mới.","cloze":"innovation"},{"en":"Mobile banking was a major innovation in Vietnam.","vi":"Ngân hàng di động là một bước đổi mới lớn ở Việt Nam.","cloze":"innovation"}]'::jsonb, '["technological innovation","encourage innovation","a major innovation"]'::jsonb, '[{"wrong":"The government should innovation the system.","right":"The government should innovate the system.","whyEn":"Innovation is a noun; the verb is innovate.","whyVi":"Innovation là danh từ; động từ là innovate."}]'::jsonb, 'B2', array['technology']::text[]);

values ('75972bee-a12d-5210-8b64-65a50246e86c', 'intention', 'intention', 'noun', '/ɪnˈtenʃn/', 'something that you plan or want to do', 'ý định, dự định: điều mình định làm hoặc muốn làm', '[{"en":"I have no intention of moving to another city.","vi":"Tôi không hề có ý định chuyển đến thành phố khác.","cloze":"intention"},{"en":"Many people start the year with good intentions about exercise.","vi":"Nhiều người bắt đầu năm mới với những dự định tốt về việc tập thể dục.","cloze":"intentions"}]'::jsonb, '["good intentions","have no intention of","the intention is to"]'::jsonb, '[{"wrong":"I have the intention to study abroad.","right":"I intend to study abroad. / I have no intention of giving up.","whyEn":"The verb ''intend to'' sounds more natural; the noun is common in ''have no intention of + -ing''.","whyVi":"Dùng động từ ''intend to'' tự nhiên hơn; danh từ hay gặp trong cụm ''have no intention of + V-ing''."}]'::jsonb, 'B1', array['society']::text[]);

values ('65352070-03c9-5eea-b372-15065da770ae', 'isolated', 'isolated', 'adjective', '/ˈaɪsəleɪtɪd/', 'separate from other things or people; not connected', 'tách biệt, rời rạc, không kết nối với những thứ hoặc người khác', '[{"en":"Older people living alone can feel very isolated in winter.","vi":"Người già sống một mình có thể cảm thấy rất cô lập vào mùa đông.","cloze":"isolated"},{"en":"These are isolated cases, not a general trend.","vi":"Đây chỉ là những trường hợp riêng lẻ, không phải xu hướng chung.","cloze":"isolated"}]'::jsonb, '["feel isolated","an isolated case","socially isolated"]'::jsonb, '[]'::jsonb, 'B2', array['society']::text[]);

values ('ab920a1a-524d-5ecb-9510-9ff5d8a37fd6', 'justify', 'justify', 'verb', '/ˈdʒʌstɪfaɪ/', 'to show that something is reasonable or worth doing', 'biện minh, chứng tỏ điều gì là hợp lý hoặc đáng làm', '[{"en":"The benefits of the new park justify the cost.","vi":"Lợi ích của công viên mới đáng với chi phí bỏ ra.","cloze":"justify"},{"en":"How can the council justify closing the library?","vi":"Hội đồng thành phố biện minh thế nào cho việc đóng cửa thư viện?","cloze":"justify"}]'::jsonb, '["justify the cost","justify a decision","hard to justify"]'::jsonb, '[{"wrong":"They justified to spend more money.","right":"They justified spending more money.","whyEn":"Justify is followed by a noun or an -ing form, not ''to'' + verb.","whyVi":"Sau justify là danh từ hoặc V-ing, không dùng ''to'' + động từ."}]'::jsonb, 'B2', array['society', 'work']::text[]);

values ('62069c49-c81f-5124-bf16-6452ff1f97b5', 'landfill', 'landfill', 'noun', '/ˈlændfɪl/', 'a place where waste is buried in the ground', 'bãi chôn lấp rác', '[{"en":"Most of our plastic waste still ends up in landfill.","vi":"Phần lớn rác nhựa của chúng ta vẫn kết thúc ở bãi chôn lấp.","cloze":"landfill"},{"en":"Recycling reduces the amount of rubbish sent to landfill sites.","vi":"Tái chế giúp giảm lượng rác đưa tới các bãi chôn lấp.","cloze":"landfill"}]'::jsonb, '["landfill site","send to landfill","end up in landfill"]'::jsonb, '[{"wrong":"The rubbish goes to the land fill.","right":"The rubbish goes to landfill.","whyEn":"Landfill is one word.","whyVi":"Landfill viết liền một từ."}]'::jsonb, 'B2', array['environment']::text[]);

values ('0f7e20a9-1278-5031-a284-870670d85c9f', 'life-expectancy', 'life expectancy', 'noun phrase', '/ˈlaɪf ɪkˌspektənsi/', 'the number of years a person is expected to live', 'tuổi thọ trung bình', '[{"en":"Life expectancy in Japan is among the highest in the world.","vi":"Tuổi thọ trung bình ở Nhật thuộc hàng cao nhất thế giới.","cloze":"Life expectancy"},{"en":"Clean water has increased life expectancy in many countries.","vi":"Nước sạch đã giúp tăng tuổi thọ trung bình ở nhiều nước.","cloze":"life expectancy"}]'::jsonb, '["average life expectancy","increase life expectancy","life expectancy at birth"]'::jsonb, '[{"wrong":"The life expectancy of Vietnam is long.","right":"Life expectancy in Vietnam is high.","whyEn":"Life expectancy is high or low, and we say in a country.","whyVi":"Tuổi thọ dùng high/low (không phải long), và nói \"in\" một quốc gia."}]'::jsonb, 'B2', array['health', 'society']::text[]);

values ('8c44e864-257d-5df8-914a-bec48622e70e', 'literacy', 'literacy', 'noun', '/ˈlɪtərəsi/', 'the ability to read and write', 'khả năng đọc và viết (biết chữ)', '[{"en":"Adult literacy has improved a lot in rural areas.","vi":"Tỉ lệ người lớn biết chữ ở nông thôn đã cải thiện nhiều.","cloze":"literacy"},{"en":"Digital literacy is now as important as maths.","vi":"Kỹ năng sử dụng công nghệ số giờ quan trọng không kém môn toán.","cloze":"literacy"}]'::jsonb, '["literacy rate","digital literacy","improve literacy"]'::jsonb, '[{"wrong":"Literacy is about literature.","right":"Literacy means being able to read and write.","whyEn":"Literacy is a basic skill, not the study of novels and poems.","whyVi":"Literacy là kỹ năng đọc viết cơ bản, không phải môn văn học (literature)."}]'::jsonb, 'B2', array['education']::text[]);

values ('59aa5caf-84ef-528b-9491-d70929293ac8', 'logistics', 'logistics', 'noun', '/ləˈdʒɪstɪks/', 'the work of moving, storing and delivering goods', 'hậu cần, logistics: vận chuyển, lưu kho và giao hàng hoá', '[{"en":"Online shopping has created many jobs in logistics.","vi":"Mua sắm trực tuyến đã tạo ra nhiều việc làm trong ngành logistics.","cloze":"logistics"},{"en":"The logistics of moving a whole office can be complicated.","vi":"Khâu hậu cần khi chuyển cả một văn phòng có thể rất phức tạp.","cloze":"logistics"}]'::jsonb, '["a logistics company","logistics network","the logistics of"]'::jsonb, '[]'::jsonb, 'C1', array['work']::text[]);

values ('b0519dd5-9302-59ea-a67b-aecda276ba33', 'nocturnal', 'nocturnal', 'adjective', '/nɒkˈtɜːnl/', '(of animals) active at night and sleeping during the day', '(động vật) hoạt động về đêm và ngủ vào ban ngày', '[{"en":"Owls are nocturnal, so they hunt after dark.","vi":"Cú là loài hoạt động về đêm, nên chúng săn mồi khi trời tối.","cloze":"nocturnal"},{"en":"Bright city lights can disturb nocturnal animals such as bats.","vi":"Ánh đèn thành phố có thể làm phiền các loài sống về đêm như dơi.","cloze":"nocturnal"}]'::jsonb, '["nocturnal animals","nocturnal species","nocturnal habits"]'::jsonb, '[]'::jsonb, 'C1', array['environment', 'science']::text[]);

values ('3e7e69a7-5434-5fbd-8139-1b4cfd6ec804', 'nutrition', 'nutrition', 'noun', '/njuˈtrɪʃn/', 'the food you eat and how it affects your health', 'dinh dưỡng', '[{"en":"Good nutrition helps children concentrate at school.","vi":"Dinh dưỡng tốt giúp trẻ tập trung ở trường.","cloze":"nutrition"},{"en":"Schools should teach basic nutrition.","vi":"Trường học nên dạy kiến thức dinh dưỡng cơ bản.","cloze":"nutrition"}]'::jsonb, '["good nutrition","poor nutrition","nutrition label"]'::jsonb, '[{"wrong":"Vegetables have a lot of nutritions.","right":"Vegetables have a lot of nutrients.","whyEn":"Nutrition is uncountable; the vitamins and minerals are nutrients.","whyVi":"Nutrition không đếm được; các chất như vitamin, khoáng chất là nutrients."}]'::jsonb, 'B1', array['health']::text[]);

values ('0f5c5556-b460-54ae-b419-33c2b53fc7de', 'obesity', 'obesity', 'noun', '/əʊˈbiːsəti/', 'the condition of being very overweight in a way that is unhealthy', 'bệnh béo phì', '[{"en":"Childhood obesity is rising in many cities.","vi":"Béo phì ở trẻ em đang tăng ở nhiều thành phố.","cloze":"obesity"},{"en":"Fast food is often blamed for obesity.","vi":"Đồ ăn nhanh thường bị đổ lỗi gây béo phì.","cloze":"obesity"}]'::jsonb, '["childhood obesity","obesity rates","tackle obesity"]'::jsonb, '[{"wrong":"Many children are obesity.","right":"Many children are obese.","whyEn":"Obesity is the noun; to describe a person, use the adjective obese.","whyVi":"Obesity là danh từ; tả một người thì dùng tính từ obese."}]'::jsonb, 'B2', array['health']::text[]);

values ('cf4ecd9a-75a7-5a5a-b70a-434597b7b942', 'observatory', 'observatory', 'noun', '/əbˈzɜːvətri/', 'a building with large telescopes for studying the sky', 'đài thiên văn: công trình có kính thiên văn lớn để quan sát bầu trời', '[{"en":"The observatory was built on a mountain where the air is clear and dry.","vi":"Đài thiên văn được xây trên núi, nơi không khí trong và khô.","cloze":"observatory"},{"en":"Students visited an observatory to look at the rings of Saturn.","vi":"Học sinh đến thăm một đài thiên văn để ngắm vành đai Sao Thổ.","cloze":"observatory"}]'::jsonb, '["a space observatory","build an observatory","observatory telescope"]'::jsonb, '[]'::jsonb, 'B2', array['science']::text[]);

values ('dace76a9-34eb-5503-bf8d-0200e33dbd87', 'obsolete', 'obsolete', 'adjective', '/ˈɒbsəliːt/', 'no longer used because something newer exists', 'lỗi thời, không còn được dùng', '[{"en":"Fax machines are almost obsolete.","vi":"Máy fax gần như đã lỗi thời.","cloze":"obsolete"},{"en":"Phones become obsolete in just a few years.","vi":"Điện thoại trở nên lỗi thời chỉ sau vài năm.","cloze":"obsolete"}]'::jsonb, '["become obsolete","obsolete technology","almost obsolete"]'::jsonb, '[{"wrong":"This phone is very old-fashion and obsolete.","right":"This phone is obsolete.","whyEn":"Obsolete already means out of date; and the adjective is old-fashioned, with -ed.","whyVi":"Obsolete đã có nghĩa \"lỗi thời\" rồi; còn nếu dùng thì phải là old-fashioned (có -ed)."}]'::jsonb, 'B2', array['technology']::text[]);

values ('29a56f55-ce74-587f-baa4-365e24dbc43a', 'pollutant', 'pollutant', 'noun', '/pəˈluːtənt/', 'a substance that makes air, water or soil dirty', 'chất gây ô nhiễm', '[{"en":"Plastic is a major pollutant in the ocean.","vi":"Nhựa là một chất gây ô nhiễm lớn trong đại dương.","cloze":"pollutant"},{"en":"Traffic releases harmful pollutants into the air.","vi":"Giao thông thải ra các chất gây ô nhiễm có hại vào không khí.","cloze":"pollutants"}]'::jsonb, '["air pollutants","harmful pollutants","release pollutants"]'::jsonb, '[{"wrong":"Factories release pollutions.","right":"Factories release pollutants.","whyEn":"Pollution is uncountable; the substances are pollutants.","whyVi":"Pollution (sự ô nhiễm) không đếm được; còn từng chất gây ô nhiễm là pollutants."}]'::jsonb, 'B2', array['environment']::text[]);

values ('a5f6c58e-7b56-50e3-aa68-ba475faedd99', 'privacy', 'privacy', 'noun', '/ˈprɪvəsi/', 'the right to keep your personal life and information to yourself', 'quyền riêng tư; sự riêng tư', '[{"en":"Social media apps collect data that can threaten our privacy.","vi":"Ứng dụng mạng xã hội thu thập dữ liệu có thể đe doạ quyền riêng tư của chúng ta.","cloze":"privacy"},{"en":"Many users never read the privacy settings.","vi":"Nhiều người dùng chẳng bao giờ đọc phần cài đặt quyền riêng tư.","cloze":"privacy"}]'::jsonb, '["protect privacy","invasion of privacy","privacy settings"]'::jsonb, '[{"wrong":"Please respect my private.","right":"Please respect my privacy.","whyEn":"Private is an adjective; privacy is the noun.","whyVi":"Private là tính từ; danh từ \"sự riêng tư\" là privacy."}]'::jsonb, 'B1', array['technology', 'society']::text[]);

values ('3bf142fd-2fb8-519f-9d25-1268d3b0b45d', 'rely', 'rely', 'verb', '/rɪˈlaɪ/', 'to need something or trust it to work', 'phụ thuộc vào; tin cậy vào', '[{"en":"Students rely on the internet for research.","vi":"Sinh viên phụ thuộc vào internet để tìm tài liệu.","cloze":"rely"},{"en":"We should not rely too much on GPS.","vi":"Chúng ta không nên quá phụ thuộc vào GPS.","cloze":"rely"}]'::jsonb, '["rely on","rely heavily on","can rely on"]'::jsonb, '[{"wrong":"People rely technology.","right":"People rely on technology.","whyEn":"Rely always needs on (or upon).","whyVi":"Rely luôn đi với on. Không có on là câu \"mất chỗ dựa\" đấy!"}]'::jsonb, 'B1', array['technology']::text[]);

values ('8ba72b86-4552-5454-990a-93b91bf2a4b5', 'renewable', 'renewable', 'adjective', '/rɪˈnjuːəbl/', '(of energy) coming from a source that does not run out, like sun or wind', 'tái tạo được (năng lượng từ nguồn không cạn kiệt như mặt trời, gió)', '[{"en":"Governments should invest more in renewable energy.","vi":"Chính phủ nên đầu tư nhiều hơn vào năng lượng tái tạo.","cloze":"renewable"},{"en":"Solar power is cheap and renewable.","vi":"Điện mặt trời vừa rẻ vừa tái tạo được.","cloze":"renewable"}]'::jsonb, '["renewable energy","renewable sources","renewable resources"]'::jsonb, '[{"wrong":"Coal is a renewable energy.","right":"Coal is a non-renewable energy source.","whyEn":"Coal, oil and gas run out, so they are non-renewable.","whyVi":"Than, dầu, khí sẽ cạn nên là non-renewable. Đừng để than đá \"đội lốt\" năng lượng xanh!"}]'::jsonb, 'B1', array['environment']::text[]);

values ('2c727290-f951-5ce7-a206-5fc9b9d66506', 'residential', 'residential', 'adjective', '/ˌrezɪˈdenʃl/', '(of an area or building) where people live, not where they work or shop', '(khu vực, toà nhà) dân cư, dùng để ở chứ không phải làm việc hay buôn bán', '[{"en":"Heavy trucks are not allowed in residential areas.","vi":"Xe tải nặng không được vào khu dân cư.","cloze":"residential"},{"en":"The old factory was turned into a residential building.","vi":"Nhà máy cũ được cải tạo thành một toà nhà ở.","cloze":"residential"}]'::jsonb, '["residential area","residential street","residential building"]'::jsonb, '[]'::jsonb, 'B2', array['cities']::text[]);

values ('5248ce1d-8b07-500b-9398-1b93c0de4158', 'sanitation', 'sanitation', 'noun', '/ˌsænɪˈteɪʃn/', 'systems that keep places clean, such as clean water and toilets', 'điều kiện vệ sinh (nước sạch, nhà vệ sinh, xử lý chất thải)', '[{"en":"Poor sanitation spreads disease quickly.","vi":"Điều kiện vệ sinh kém làm bệnh lây lan nhanh.","cloze":"sanitation"},{"en":"Better sanitation has raised life expectancy around the world.","vi":"Vệ sinh tốt hơn đã giúp tăng tuổi thọ trên toàn thế giới.","cloze":"sanitation"}]'::jsonb, '["poor sanitation","improve sanitation","sanitation facilities"]'::jsonb, '[{"wrong":"The hospital needs more sanitations.","right":"The area needs better sanitation.","whyEn":"Sanitation is uncountable; describe it as better or poor.","whyVi":"Sanitation không đếm được; hãy nói better/poor sanitation."}]'::jsonb, 'B2', array['health']::text[]);

values ('48e32ee9-a091-5f5a-81b4-a08411155e9b', 'scholarship', 'scholarship', 'noun', '/ˈskɒləʃɪp/', 'money given to a student to help pay for their studies', 'học bổng', '[{"en":"She won a scholarship to study engineering abroad.","vi":"Cô ấy giành được học bổng du học ngành kỹ thuật.","cloze":"scholarship"},{"en":"A full scholarship covers tuition and living costs.","vi":"Học bổng toàn phần chi trả cả học phí lẫn chi phí sinh hoạt.","cloze":"scholarship"}]'::jsonb, '["win a scholarship","full scholarship","apply for a scholarship"]'::jsonb, '[{"wrong":"He got a scholarship of Oxford.","right":"He got a scholarship to Oxford.","whyEn":"A scholarship is to a university, or to study something.","whyVi":"Học bổng \"to\" một trường hoặc \"to study\" một ngành, không dùng \"of\"."}]'::jsonb, 'B1', array['education']::text[]);

values ('939e84bd-4650-5438-a632-c7547692aeb1', 'sedentary', 'sedentary', 'adjective', '/ˈsedntri/', 'involving a lot of sitting and little exercise', 'ít vận động, ngồi nhiều', '[{"en":"Office workers often have a sedentary lifestyle.","vi":"Dân văn phòng thường có lối sống ít vận động.","cloze":"sedentary"},{"en":"Long hours of gaming are very sedentary.","vi":"Chơi game nhiều giờ liền là hoạt động rất ít vận động.","cloze":"sedentary"}]'::jsonb, '["sedentary lifestyle","sedentary job","sedentary behaviour"]'::jsonb, '[{"wrong":"He has a sedentary sport.","right":"He has a sedentary job.","whyEn":"Sedentary means with little movement, so it does not fit sport.","whyVi":"Sedentary là \"ít vận động\", ghép với sport là tự mâu thuẫn. Môn thể thao ngồi im thì chắc là ngủ!"}]'::jsonb, 'B2', array['health']::text[]);

values ('ff29ef54-fa36-5418-a54d-0f259a72210c', 'sustainable', 'sustainable', 'adjective', '/səˈsteɪnəbl/', 'able to continue for a long time without damaging the environment', 'bền vững: duy trì lâu dài mà không hại môi trường', '[{"en":"Cities need sustainable transport, such as trams and cycle lanes.","vi":"Các thành phố cần giao thông bền vững như tàu điện và làn xe đạp.","cloze":"sustainable"},{"en":"Is cheap fast fashion really sustainable?","vi":"Thời trang nhanh giá rẻ có thật sự bền vững không?","cloze":"sustainable"}]'::jsonb, '["sustainable development","sustainable energy","environmentally sustainable"]'::jsonb, '[{"wrong":"We need more sustainability transport.","right":"We need more sustainable transport.","whyEn":"Before a noun, use the adjective sustainable, not the noun sustainability.","whyVi":"Đứng trước danh từ thì dùng tính từ sustainable, không dùng danh từ sustainability."}]'::jsonb, 'B2', array['environment']::text[]);

values ('237e84e3-7696-533a-b154-dc05d408059b', 'symptom', 'symptom', 'noun', '/ˈsɪmptəm/', 'a sign that you are ill, such as a fever or a cough', 'triệu chứng', '[{"en":"A high temperature is a common symptom of flu.","vi":"Sốt cao là triệu chứng phổ biến của cúm.","cloze":"symptom"},{"en":"Stress can cause physical symptoms like headaches.","vi":"Căng thẳng có thể gây ra triệu chứng thể chất như đau đầu.","cloze":"symptoms"}]'::jsonb, '["common symptoms","early symptoms","show symptoms"]'::jsonb, '[{"wrong":"Symptoms for flu include fever.","right":"Symptoms of flu include fever.","whyEn":"We say symptoms of an illness.","whyVi":"Triệu chứng \"của\" bệnh dùng \"of\", không dùng \"for\"."}]'::jsonb, 'B1', array['health']::text[]);

values ('b17895e4-cdef-524e-9dd1-f5e9150091f2', 'tuition', 'tuition', 'noun', '/tjuˈɪʃn/', 'teaching, or the money you pay for it at a college or university', 'việc giảng dạy, hoặc học phí phải trả cho trường', '[{"en":"Rising tuition fees stop some students from going to university.","vi":"Học phí tăng khiến một số học sinh không thể vào đại học.","cloze":"tuition"},{"en":"She pays for extra tuition in maths before the exam.","vi":"Cô ấy trả tiền học thêm môn toán trước kỳ thi.","cloze":"tuition"}]'::jsonb, '["tuition fees","free tuition","private tuition"]'::jsonb, '[{"wrong":"The tuition is very expensive money.","right":"Tuition fees are very high.","whyEn":"Fees are high or low; we do not say \"expensive money\".","whyVi":"Học phí thì \"high/low\", không nói \"expensive money\" (dịch thẳng từ \"tiền đắt\")."}]'::jsonb, 'B1', array['education']::text[]);

values ('b08c26e1-2141-56f8-b8d6-04df519f0b7e', 'vaccine', 'vaccine', 'noun', '/ˈvæksiːn/', 'a substance given to people to protect them from a disease', 'vắc-xin', '[{"en":"The new vaccine protects children against measles.","vi":"Loại vắc-xin mới bảo vệ trẻ khỏi bệnh sởi.","cloze":"vaccine"},{"en":"Scientists developed several vaccines in record time.","vi":"Các nhà khoa học đã phát triển nhiều loại vắc-xin trong thời gian kỷ lục.","cloze":"vaccines"}]'::jsonb, '["develop a vaccine","vaccine against","flu vaccine"]'::jsonb, '[{"wrong":"I vaccine my dog every year.","right":"I vaccinate my dog every year.","whyEn":"Vaccine is the noun; the verb is vaccinate.","whyVi":"Vaccine là danh từ; động từ \"tiêm phòng\" là vaccinate."}]'::jsonb, 'B1', array['health', 'science']::text[]);

values ('a7686b03-1e79-50a4-9ec9-aa1ecfba681c', 'vegetation', 'vegetation', 'noun', '/ˌvedʒəˈteɪʃn/', 'plants in general, especially those growing in a particular area', 'cây cối, thảm thực vật nói chung ở một khu vực', '[{"en":"Thick vegetation covers the hills after the rainy season.","vi":"Cây cối rậm rạp phủ kín các ngọn đồi sau mùa mưa.","cloze":"vegetation"},{"en":"Removing vegetation from riverbanks can increase the risk of floods.","vi":"Phá bỏ thảm thực vật ven sông có thể làm tăng nguy cơ lũ lụt.","cloze":"vegetation"}]'::jsonb, '["dense vegetation","natural vegetation","a layer of vegetation"]'::jsonb, '[{"wrong":"There are many vegetations on the roof.","right":"There is a lot of vegetation on the roof.","whyEn":"Vegetation is uncountable, so it has no plural and takes ''a lot of'' or ''much''.","whyVi":"Vegetation là danh từ không đếm được, không có dạng số nhiều và đi với ''a lot of'' hoặc ''much''."}]'::jsonb, 'B2', array['environment']::text[]);

values ('f80b2790-8104-5360-83d0-158039127771', 'vocational', 'vocational', 'adjective', '/vəʊˈkeɪʃənl/', 'teaching the skills you need for a particular job', '(thuộc) dạy nghề, đào tạo kỹ năng cho một nghề cụ thể', '[{"en":"Vocational courses can lead straight to a well-paid job.","vi":"Các khoá học nghề có thể dẫn thẳng tới một công việc lương tốt.","cloze":"Vocational"},{"en":"Not every teenager wants to go to university; some prefer vocational training.","vi":"Không phải thiếu niên nào cũng muốn vào đại học; có bạn thích học nghề hơn.","cloze":"vocational"}]'::jsonb, '["vocational training","vocational school","vocational skills"]'::jsonb, '[{"wrong":"He went to a vacation school.","right":"He went to a vocational school.","whyEn":"Vacation means a holiday. Vocational is about job skills.","whyVi":"Vacation là kỳ nghỉ, còn vocational là học nghề. Học nghề không phải đi nghỉ đâu nhé!"}]'::jsonb, 'B2', array['education', 'work']::text[]);

values ('e9a435ab-6274-57ec-a2db-381e18c9ac14', 'well-being', 'well-being', 'noun', '/ˈwel biːɪŋ/', 'the state of being healthy, happy and comfortable', 'sức khoẻ và tinh thần tốt; sự an lạc', '[{"en":"Green spaces improve the mental well-being of city residents.","vi":"Mảng xanh giúp cải thiện sức khoẻ tinh thần của cư dân thành phố.","cloze":"well-being"},{"en":"Companies should care about their employees'' well-being.","vi":"Công ty nên quan tâm đến sức khoẻ và tinh thần của nhân viên.","cloze":"well-being"}]'::jsonb, '["mental well-being","sense of well-being","improve well-being"]'::jsonb, '[{"wrong":"Exercise is good for our well-beings.","right":"Exercise is good for our well-being.","whyEn":"Well-being is uncountable.","whyVi":"Well-being không đếm được, không thêm -s."}]'::jsonb, 'B2', array['health']::text[]);

-- vocabulary set education (published, v1)
values ('db023de5-d86b-55b9-8801-338313736fb3', 'vocabulary_set', 'education', 'Education', 'Words for talking about schools, universities and learning, the IELTS topic that never goes away.', 'B1', array['education']::text[], 'ai_assisted', 'published', 1);

-- vocabulary set environment (published, v1)
values ('e15db8ce-50a3-5274-824b-977b3b6fd808', 'vocabulary_set', 'environment', 'Environment', 'Words for pollution, climate and nature, ready for Writing Task 2 and Speaking Part 3.', 'B2', array['environment']::text[], 'ai_assisted', 'published', 1);

-- vocabulary set health (published, v1)
values ('b986b0bd-da59-575b-947a-b5f09b5df3bb', 'vocabulary_set', 'health', 'Health', 'Words for diet, exercise and public health, useful in Writing Task 2 and Speaking.', 'B1', array['health']::text[], 'ai_assisted', 'published', 1);

-- vocabulary set technology (published, v1)
values ('987097e7-f2c0-5e0b-9ed3-db310566cac8', 'vocabulary_set', 'technology', 'Technology', 'Words for gadgets, the internet and how technology changes our lives.', 'B1', array['technology']::text[], 'ai_assisted', 'published', 1);

-- grammar topic articles (published, v1)
values ('1e3e7fe6-7a1d-574f-9e73-d881cef461f0', 'grammar_topic', 'articles', 'Articles: a, an, the', 'Tiny words with big jobs: choose a, an, the or nothing at all.', 'B1', array[]::text[], 'ai_assisted', 'published', 1);
-- articles-practice (published, v1)
values ('8a7ebd58-11ca-50d0-9d81-f525a459a9f1', 'practice_set', 'articles-practice', 'Articles: a, an, the — practice', null, 'B1', array[]::text[], 'ai_assisted', 'published', 1);
values ('8a7ebd58-11ca-50d0-9d81-f525a459a9f1', 'grammar', 'practice', null);
values ('e70996aa-3e33-588b-86c5-34aa67d3260f', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', null, 1, 'multiple_choice', 'Choose the correct option.', null);
values ('30ec0263-b403-5451-90d2-10ba752d8024', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', 'e70996aa-3e33-588b-86c5-34aa67d3260f', 1, 1, 'She wants to become ___ engineer.', '[{"id":"A","text":"a"},{"id":"B","text":"an"},{"id":"C","text":"the"}]'::jsonb, 'single', null, null);
values ('30ec0263-b403-5451-90d2-10ba752d8024', '["B"]'::jsonb, 'Engineer starts with a vowel sound, so we use an. It is one engineer among many, so not the.', 'Engineer bắt đầu bằng nguyên âm nên dùng an. Đây là một kỹ sư bất kỳ, nên không dùng the.', null, null, null);
values ('12d9c88e-33fa-501c-93da-e36cf2f885a8', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', 'e70996aa-3e33-588b-86c5-34aa67d3260f', 2, 2, '___ moon looks huge tonight!', '[{"id":"A","text":"A"},{"id":"B","text":"The"},{"id":"C","text":"No article"}]'::jsonb, 'single', null, null);
values ('12d9c88e-33fa-501c-93da-e36cf2f885a8', '["B"]'::jsonb, 'There is only one moon, so we use the.', 'Chỉ có một mặt trăng, nên dùng the. Trừ khi bạn đang ở hành tinh khác!', null, null, null);
values ('464ea3be-4f23-529c-9a88-c5e3533282f6', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', 'e70996aa-3e33-588b-86c5-34aa67d3260f', 3, 3, '___ smoking is banned in most restaurants.', '[{"id":"A","text":"The"},{"id":"B","text":"A"},{"id":"C","text":"No article"}]'::jsonb, 'single', null, null);
values ('464ea3be-4f23-529c-9a88-c5e3533282f6', '["C"]'::jsonb, 'Smoking here is an activity in general, so no article.', 'Smoking ở đây là hoạt động nói chung, nên không dùng mạo từ.', null, null, null);
values ('26585356-e955-5d1f-858b-cee42f16d7a9', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', null, 2, 'gap_fill', 'Write the missing article: a, an or the.', null);
values ('2a8daf60-f6be-5a72-a655-93174216e057', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', '26585356-e955-5d1f-858b-cee42f16d7a9', 1, 4, 'I read ___ interesting article about climate change.', null, 'text', null, 1);
values ('2a8daf60-f6be-5a72-a655-93174216e057', '["an"]'::jsonb, 'Interesting starts with a vowel sound, and it is the first time we mention the article.', 'Interesting bắt đầu bằng nguyên âm, và đây là lần đầu nhắc tới bài báo nên dùng an.', null, null, null);
values ('4a4b460e-8ea5-5011-9a97-311b82a7c86d', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', '26585356-e955-5d1f-858b-cee42f16d7a9', 2, 5, 'Can you pass me ___ salt, please?', null, 'text', null, 1);
values ('4a4b460e-8ea5-5011-9a97-311b82a7c86d', '["the"]'::jsonb, 'We both know which salt: the one on the table.', 'Cả hai đều biết là lọ muối nào: lọ trên bàn. Nên dùng the.', null, null, null);
values ('c23c7dde-c980-547a-afde-9d73c73e0a0c', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', null, 3, 'error_correction', 'Spot the mistake: tap the word that is wrong.', null);
values ('b6ed2302-a7c6-5822-917e-5f946ae67f1c', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', 'c23c7dde-c980-547a-afde-9d73c73e0a0c', 1, 6, 'He is a honest man.', '[{"id":"t1","text":"He"},{"id":"t2","text":"is"},{"id":"t3","text":"a"},{"id":"t4","text":"honest"},{"id":"t5","text":"man."}]'::jsonb, 'single', null, null);
values ('b6ed2302-a7c6-5822-917e-5f946ae67f1c', '["t3"]'::jsonb, 'The h in honest is silent, so it starts with a vowel sound: an honest man.', 'Chữ h trong honest câm, âm đầu là nguyên âm: an honest man. Chữ h này "im lặng là vàng".', null, null, 'He is an honest man.');
values ('8c468aad-c31c-5918-a2bd-993b64546b35', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', 'c23c7dde-c980-547a-afde-9d73c73e0a0c', 2, 7, 'The pollution is a serious problem in big cities.', '[{"id":"t1","text":"The"},{"id":"t2","text":"pollution"},{"id":"t3","text":"is"},{"id":"t4","text":"a"},{"id":"t5","text":"serious"},{"id":"t6","text":"problem"},{"id":"t7","text":"in"},{"id":"t8","text":"big"},{"id":"t9","text":"cities."}]'::jsonb, 'single', null, null);
values ('8c468aad-c31c-5918-a2bd-993b64546b35', '["t1"]'::jsonb, 'Pollution in general takes no article.', 'Ô nhiễm nói chung thì không dùng mạo từ.', null, null, 'Pollution is a serious problem in big cities.');
values ('af0e99f1-54de-5901-b28f-96d185fe8040', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', null, 4, 'sentence_transformation', 'Rewrite the sentence correctly.', null);
values ('d4aca0bf-adb2-59b7-a1a5-7b3af103d561', '8a7ebd58-11ca-50d0-9d81-f525a459a9f1', 'af0e99f1-54de-5901-b28f-96d185fe8040', 1, 8, 'My sister is doctor in a big hospital.', null, 'text', null, null);
values ('d4aca0bf-adb2-59b7-a1a5-7b3af103d561', '["My sister is a doctor in a big hospital."]'::jsonb, 'A job with a singular noun needs a: a doctor.', 'Nghề nghiệp với danh từ số ít cần a: a doctor.', null, null, null);
values ('1e3e7fe6-7a1d-574f-9e73-d881cef461f0', 1, '{"introEn":"A, an and the are tiny words with big jobs. Examiners see them in almost every sentence you write, so a few clear rules can quickly lift your grammar score.","introVi":"A, an và the nhỏ xíu nhưng gánh việc to. Giám khảo gặp chúng trong gần như mọi câu bạn viết, nên chỉ cần nắm vài quy tắc rõ ràng là điểm ngữ pháp \"lên tay\" ngay.","sections":[{"heading":"A or an? Listen, don''t look","bodyEn":"Choose by the first sound, not the first letter. Use an before a vowel sound and a before a consonant sound.","bodyVi":"Chọn theo âm đầu, đừng nhìn chữ cái đầu. Trước nguyên âm dùng an, trước phụ âm dùng a. Tai quan trọng hơn mắt ở đây!","examples":[{"en":"an hour","vi":"một giờ","note":"The h is silent, so the first sound is a vowel."},{"en":"a university","vi":"một trường đại học","note":"U sounds like \"you\", a consonant sound."},{"en":"an MBA","vi":"một bằng MBA","note":"M is said \"em\", which starts with a vowel sound."}]},{"heading":"The: we both know which one","bodyEn":"Use the when your listener knows exactly which thing you mean: you mentioned it before, it is the only one, or the rest of the sentence makes it clear.","bodyVi":"Dùng the khi người nghe biết chính xác bạn nói cái nào: đã nhắc trước đó, là cái duy nhất, hoặc phần còn lại của câu đã chỉ rõ.","examples":[{"en":"I bought a laptop. The laptop was surprisingly cheap.","vi":"Tôi mua một chiếc laptop. Chiếc laptop đó rẻ bất ngờ."},{"en":"The sun rises in the east.","vi":"Mặt trời mọc ở hướng đông.","note":"There is only one sun."},{"en":"The students in my class are friendly.","vi":"Các bạn trong lớp tôi rất thân thiện.","note":"\"In my class\" tells us which students."}]},{"heading":"No article for things in general","bodyEn":"When you talk about things in general, use a plural or uncountable noun with no article at all.","bodyVi":"Khi nói về sự vật nói chung, dùng danh từ số nhiều hoặc không đếm được và bỏ hẳn mạo từ.","examples":[{"en":"Children need plenty of sleep.","vi":"Trẻ em cần ngủ đủ.","note":"All children, in general."},{"en":"Technology changes how we learn.","vi":"Công nghệ thay đổi cách chúng ta học."},{"en":"Pollution is a serious problem.","vi":"Ô nhiễm là vấn đề nghiêm trọng."}]}],"commonMistakes":[{"wrong":"The technology changes our lives.","right":"Technology changes our lives.","whyEn":"This is a general statement, so no article.","whyVi":"Đây là ý nói chung nên bỏ the. Khi dịch từ tiếng Việt, ta hay thêm \"the\" như thêm chữ \"cái\" vậy."},{"wrong":"She is a honest teacher.","right":"She is an honest teacher.","whyEn":"Honest starts with a vowel sound because the h is silent.","whyVi":"Chữ h trong honest câm, âm đầu là nguyên âm nên dùng an."},{"wrong":"I am student.","right":"I am a student.","whyEn":"A singular countable noun, such as a job, needs a or an.","whyVi":"Tiếng Việt không có mạo từ nên ta hay quên; danh từ đếm được số ít (như nghề nghiệp) cần a/an."}],"ieltsTipEn":"Writing Task 2 is full of general statements. Before you finish, check every \"the\" in front of a general idea: \"The education is important\" should be \"Education is important\".","ieltsTipVi":"Writing Task 2 toàn câu nói chung. Trước khi nộp, soát từng chữ \"the\" đứng trước một ý chung: \"The education is important\" phải là \"Education is important\"."}'::jsonb, '8a7ebd58-11ca-50d0-9d81-f525a459a9f1');

-- grammar topic conditionals (published, v1)
values ('ad1fc239-a491-5856-b1b8-536ea95333d4', 'grammar_topic', 'conditionals', 'Conditionals: first and second', 'Real possibilities vs imaginary situations: if + will, or if + would.', 'B1', array[]::text[], 'ai_assisted', 'published', 1);
-- conditionals-practice (published, v1)
values ('793edb7a-981f-56c1-aaae-643a5cbaedac', 'practice_set', 'conditionals-practice', 'Conditionals: first and second — practice', null, 'B1', array[]::text[], 'ai_assisted', 'published', 1);
values ('793edb7a-981f-56c1-aaae-643a5cbaedac', 'grammar', 'practice', null);
values ('d1a6c4a8-7545-5266-b13b-7dcd169971f1', '793edb7a-981f-56c1-aaae-643a5cbaedac', null, 1, 'multiple_choice', 'Choose the correct option.', null);
values ('62b07ea0-a646-5ef3-8523-36a39804c285', '793edb7a-981f-56c1-aaae-643a5cbaedac', 'd1a6c4a8-7545-5266-b13b-7dcd169971f1', 1, 1, 'If it ___ tomorrow, we''ll cancel the picnic.', '[{"id":"A","text":"rains"},{"id":"B","text":"will rain"},{"id":"C","text":"rained"}]'::jsonb, 'single', null, null);
values ('62b07ea0-a646-5ef3-8523-36a39804c285', '["A"]'::jsonb, 'A real future possibility: if + present simple.', 'Khả năng có thật trong tương lai: if + hiện tại đơn.', null, null, null);
values ('6f9c8fe6-bc2b-54ac-9773-18859577cbcb', '793edb7a-981f-56c1-aaae-643a5cbaedac', 'd1a6c4a8-7545-5266-b13b-7dcd169971f1', 2, 2, 'If I ___ you, I would talk to the teacher.', '[{"id":"A","text":"am"},{"id":"B","text":"were"},{"id":"C","text":"will be"}]'::jsonb, 'single', null, null);
values ('6f9c8fe6-bc2b-54ac-9773-18859577cbcb', '["B"]'::jsonb, 'I am not you, so it is imaginary: if I were you.', 'Tôi đâu phải bạn, nên đây là tưởng tượng: if I were you.', null, null, null);
values ('86acfde9-ae38-5032-91a0-492cb7e769b9', '793edb7a-981f-56c1-aaae-643a5cbaedac', 'd1a6c4a8-7545-5266-b13b-7dcd169971f1', 3, 3, 'If more people used public transport, there ___ less traffic.', '[{"id":"A","text":"will be"},{"id":"B","text":"would be"},{"id":"C","text":"is"}]'::jsonb, 'single', null, null);
values ('86acfde9-ae38-5032-91a0-492cb7e769b9', '["B"]'::jsonb, 'Used (past) in the if-clause pairs with would.', 'Vế if dùng used (quá khứ) thì vế kết quả dùng would.', null, null, null);
values ('ecedfd9b-27e0-550e-9425-f3d2260d380d', '793edb7a-981f-56c1-aaae-643a5cbaedac', null, 2, 'gap_fill', 'Write the correct form of the verb in brackets.', null);
values ('3ecfdd16-3fa3-56a1-b69b-fc2c67b26cb7', '793edb7a-981f-56c1-aaae-643a5cbaedac', 'ecedfd9b-27e0-550e-9425-f3d2260d380d', 1, 4, 'If she studies hard, she ___ (pass) the exam.', null, 'text', null, 2);
values ('3ecfdd16-3fa3-56a1-b69b-fc2c67b26cb7', '["will pass"]'::jsonb, 'A real possibility: present simple after if, will in the result.', 'Khả năng có thật: hiện tại đơn sau if, will ở vế kết quả.', null, null, null);
values ('58a165a5-18ee-54af-9a74-f7a8db3e9fde', '793edb7a-981f-56c1-aaae-643a5cbaedac', 'ecedfd9b-27e0-550e-9425-f3d2260d380d', 2, 5, 'If I ___ (have) more free time, I would learn the guitar.', null, 'text', null, 1);
values ('58a165a5-18ee-54af-9a74-f7a8db3e9fde', '["had"]'::jsonb, 'Would in the result means the if-clause takes the past simple.', 'Vế kết quả có would thì vế if dùng quá khứ đơn.', null, null, null);
values ('68931ed4-77d3-5d30-9694-9f06bcbec5c5', '793edb7a-981f-56c1-aaae-643a5cbaedac', null, 3, 'error_correction', 'Spot the mistake: tap the word that is wrong.', null);
values ('3d5b30c7-e2ae-52b4-ae5b-bec07e3b29c1', '793edb7a-981f-56c1-aaae-643a5cbaedac', '68931ed4-77d3-5d30-9694-9f06bcbec5c5', 1, 6, 'If it will snow, the flight may be delayed.', '[{"id":"t1","text":"If"},{"id":"t2","text":"it"},{"id":"t3","text":"will"},{"id":"t4","text":"snow,"},{"id":"t5","text":"the"},{"id":"t6","text":"flight"},{"id":"t7","text":"may"},{"id":"t8","text":"be"},{"id":"t9","text":"delayed."}]'::jsonb, 'single', null, null);
values ('3d5b30c7-e2ae-52b4-ae5b-bec07e3b29c1', '["t3"]'::jsonb, 'No will after if for a future condition.', 'Sau if không dùng will cho điều kiện tương lai.', null, null, 'If it snows, the flight may be delayed.');
values ('d1e91eb4-03e7-515c-bed0-548f265d2923', '793edb7a-981f-56c1-aaae-643a5cbaedac', '68931ed4-77d3-5d30-9694-9f06bcbec5c5', 2, 7, 'If I have a car, I would drive to work.', '[{"id":"t1","text":"If"},{"id":"t2","text":"I"},{"id":"t3","text":"have"},{"id":"t4","text":"a"},{"id":"t5","text":"car,"},{"id":"t6","text":"I"},{"id":"t7","text":"would"},{"id":"t8","text":"drive"},{"id":"t9","text":"to"},{"id":"t10","text":"work."}]'::jsonb, 'single', null, null);
values ('d1e91eb4-03e7-515c-bed0-548f265d2923', '["t3"]'::jsonb, 'Would needs a past verb in the if-clause: had.', 'Có would thì vế if cần động từ quá khứ: had.', null, null, 'If I had a car, I would drive to work.');
values ('7a82d74a-0c9d-5ef8-b08f-396fd8960886', '793edb7a-981f-56c1-aaae-643a5cbaedac', null, 4, 'sentence_transformation', 'Rewrite the sentence starting with If.', null);
values ('99c8587b-7dd7-5f90-b148-2aa8e15ef9a5', '793edb7a-981f-56c1-aaae-643a5cbaedac', '7a82d74a-0c9d-5ef8-b08f-396fd8960886', 1, 8, 'I don''t have enough time, so I can''t exercise. (If…)', null, 'text', null, null);
values ('99c8587b-7dd7-5f90-b148-2aa8e15ef9a5', '["If I had enough time, I could exercise.","If I had enough time, I would exercise.","If I had enough time I could exercise.","If I had enough time I would exercise."]'::jsonb, 'The real situation is the opposite, so use the second conditional: if + past, could/would.', 'Thực tế là ngược lại, nên dùng câu điều kiện loại 2: if + quá khứ, could/would.', null, null, null);
values ('ad1fc239-a491-5856-b1b8-536ea95333d4', 3, '{"introEn":"Conditionals let you talk about results: what will happen, or what would happen. The question to ask yourself is how real the situation feels.","introVi":"Câu điều kiện giúp bạn nói về kết quả: điều gì sẽ xảy ra, hoặc điều gì sẽ xảy ra nếu như... Câu cần tự hỏi là: tình huống này thật đến mức nào?","sections":[{"heading":"First conditional: it could really happen","bodyEn":"For real possibilities in the future: if + present simple, will + verb. No will after if!","bodyVi":"Cho khả năng có thật trong tương lai: if + hiện tại đơn, will + động từ. Sau if không dùng will nhé!","examples":[{"en":"If it rains tomorrow, we will stay at home.","vi":"Nếu mai trời mưa, chúng tôi sẽ ở nhà."},{"en":"If you practise every day, your speaking will improve.","vi":"Nếu bạn luyện mỗi ngày, kỹ năng nói sẽ tiến bộ."}]},{"heading":"Second conditional: only in your imagination","bodyEn":"For imaginary or unlikely situations, now or in the future: if + past simple, would + verb. The past tense here does not mean past time; it means \"not real\".","bodyVi":"Cho tình huống tưởng tượng hoặc khó xảy ra, ở hiện tại hay tương lai: if + quá khứ đơn, would + động từ. Thì quá khứ ở đây không phải chuyện đã qua, mà nghĩa là \"không có thật\".","examples":[{"en":"If I won the lottery, I would travel the world.","vi":"Nếu trúng xổ số, tôi sẽ đi du lịch khắp thế giới.","note":"Nice dream, unlikely reality."},{"en":"If I were you, I would talk to the teacher.","vi":"Nếu tôi là bạn, tôi sẽ nói chuyện với giáo viên.","note":"In careful English, use were for all persons."}]},{"heading":"Choosing between them","bodyEn":"The same idea can use either form. It depends on how likely you think it is. \"If I get the job\" sounds hopeful; \"If I got the job\" sounds like a dream.","bodyVi":"Cùng một ý có thể dùng cả hai, tuỳ bạn thấy nó có khả năng đến đâu. \"If I get the job\" nghe đầy hy vọng; \"If I got the job\" nghe như đang mơ.","examples":[{"en":"If I pass IELTS, I will apply for a scholarship.","vi":"Nếu đỗ IELTS, tôi sẽ nộp đơn xin học bổng.","note":"A real plan."},{"en":"If I spoke ten languages, I would work for the UN.","vi":"Nếu nói được mười thứ tiếng, tôi sẽ làm cho Liên Hợp Quốc.","note":"Pure imagination."}]}],"commonMistakes":[{"wrong":"If it will rain, we will stay at home.","right":"If it rains, we will stay at home.","whyEn":"In the if-clause, use the present simple, not will.","whyVi":"Trong mệnh đề if dùng hiện tại đơn, không dùng will. Will chỉ ở vế kết quả."},{"wrong":"If I have more money, I would buy a car.","right":"If I had more money, I would buy a car.","whyEn":"Would goes with a past verb in the if-clause.","whyVi":"Would đi cặp với động từ quá khứ ở vế if. Đừng \"ghép đôi\" lộn xộn."}],"ieltsTipEn":"In Writing Task 2, the second conditional is great for proposals: \"If governments taxed sugary drinks, fewer people would buy them.\" It shows range and sounds balanced.","ieltsTipVi":"Trong Writing Task 2, câu điều kiện loại 2 rất hợp để đề xuất giải pháp: \"If governments taxed sugary drinks, fewer people would buy them.\" Vừa thể hiện sự đa dạng ngữ pháp, vừa nghe khách quan."}'::jsonb, '793edb7a-981f-56c1-aaae-643a5cbaedac');

-- grammar topic present-perfect-vs-past-simple (published, v1)
values ('d5cc9b6d-b272-5029-a6f0-21702e2c02a7', 'grammar_topic', 'present-perfect-vs-past-simple', 'Present perfect vs past simple', 'Finished past or connected to now? The time words decide.', 'B1', array[]::text[], 'ai_assisted', 'published', 1);
-- present-perfect-vs-past-simple-practice (published, v1)
values ('28021070-9997-5d20-a09d-95c6a0706792', 'practice_set', 'present-perfect-vs-past-simple-practice', 'Present perfect vs past simple — practice', null, 'B1', array[]::text[], 'ai_assisted', 'published', 1);
values ('28021070-9997-5d20-a09d-95c6a0706792', 'grammar', 'practice', null);
values ('9f035a10-7ad5-5a5f-8135-57fc64df1aea', '28021070-9997-5d20-a09d-95c6a0706792', null, 1, 'multiple_choice', 'Choose the correct option.', null);
values ('fe65f1a8-b063-5912-92f5-14e41e6ab30a', '28021070-9997-5d20-a09d-95c6a0706792', '9f035a10-7ad5-5a5f-8135-57fc64df1aea', 1, 1, 'I ___ my keys. I can''t open the door!', '[{"id":"A","text":"lost"},{"id":"B","text":"have lost"},{"id":"C","text":"was losing"}]'::jsonb, 'single', null, null);
values ('fe65f1a8-b063-5912-92f5-14e41e6ab30a', '["B"]'::jsonb, 'The result is now (I can''t open the door), so use the present perfect.', 'Kết quả ở hiện tại (không mở được cửa), nên dùng hiện tại hoàn thành.', null, null, null);
values ('3d06ad98-d33e-5791-b58d-912a86746f5f', '28021070-9997-5d20-a09d-95c6a0706792', '9f035a10-7ad5-5a5f-8135-57fc64df1aea', 2, 2, 'We ___ to Nha Trang in 2019.', '[{"id":"A","text":"have gone"},{"id":"B","text":"went"},{"id":"C","text":"have been"}]'::jsonb, 'single', null, null);
values ('3d06ad98-d33e-5791-b58d-912a86746f5f', '["B"]'::jsonb, 'In 2019 is a finished time, so use the past simple.', 'Năm 2019 đã qua, nên dùng quá khứ đơn.', null, null, null);
values ('cd70a6d8-462c-5721-9ef3-1542e3acbf9c', '28021070-9997-5d20-a09d-95c6a0706792', '9f035a10-7ad5-5a5f-8135-57fc64df1aea', 3, 3, 'How long ___ English?', '[{"id":"A","text":"do you study"},{"id":"B","text":"did you study"},{"id":"C","text":"have you studied"}]'::jsonb, 'single', null, null);
values ('cd70a6d8-462c-5721-9ef3-1542e3acbf9c', '["C"]'::jsonb, 'How long asks about time up to now, so use the present perfect.', 'How long hỏi khoảng thời gian tới bây giờ, nên dùng hiện tại hoàn thành.', null, null, null);
values ('2eb937b8-7a2c-5faa-9602-a64a01029791', '28021070-9997-5d20-a09d-95c6a0706792', null, 2, 'gap_fill', 'Write the correct form of the verb in brackets.', null);
values ('ef7857fa-3766-5ebb-9c31-f438c013f292', '28021070-9997-5d20-a09d-95c6a0706792', '2eb937b8-7a2c-5faa-9602-a64a01029791', 1, 4, 'She ___ (not finish) her essay yet.', null, 'text', null, 3);
values ('ef7857fa-3766-5ebb-9c31-f438c013f292', '["hasn''t finished","has not finished"]'::jsonb, 'Yet goes with the present perfect.', 'Yet đi với hiện tại hoàn thành.', null, null, null);
values ('bc314a8d-113a-5861-bcf1-9613aedce417', '28021070-9997-5d20-a09d-95c6a0706792', '2eb937b8-7a2c-5faa-9602-a64a01029791', 2, 5, 'Two years ago, my family ___ (move) to Hanoi.', null, 'text', null, 1);
values ('bc314a8d-113a-5861-bcf1-9613aedce417', '["moved"]'::jsonb, 'Ago marks a finished time, so use the past simple.', 'Ago chỉ thời điểm đã qua, nên dùng quá khứ đơn.', null, null, null);
values ('394d1713-749c-5849-a906-7b0b20e8f1e8', '28021070-9997-5d20-a09d-95c6a0706792', null, 3, 'error_correction', 'Spot the mistake: tap the word that is wrong.', null);
values ('4b32ae51-5c0e-5b3a-bedf-2ee9bd138e98', '28021070-9997-5d20-a09d-95c6a0706792', '394d1713-749c-5849-a906-7b0b20e8f1e8', 1, 6, 'I have seen that film last week.', '[{"id":"t1","text":"I"},{"id":"t2","text":"have"},{"id":"t3","text":"seen"},{"id":"t4","text":"that"},{"id":"t5","text":"film"},{"id":"t6","text":"last"},{"id":"t7","text":"week."}]'::jsonb, 'single', null, null);
values ('4b32ae51-5c0e-5b3a-bedf-2ee9bd138e98', '["t2"]'::jsonb, 'Last week is finished time, so we need the past simple: saw.', 'Last week đã kết thúc, nên dùng quá khứ đơn: saw.', null, null, 'I saw that film last week.');
values ('91d21eed-d2d4-5e39-bbf6-62a39177ea4b', '28021070-9997-5d20-a09d-95c6a0706792', '394d1713-749c-5849-a906-7b0b20e8f1e8', 2, 7, 'She works here since 2020.', '[{"id":"t1","text":"She"},{"id":"t2","text":"works"},{"id":"t3","text":"here"},{"id":"t4","text":"since"},{"id":"t5","text":"2020."}]'::jsonb, 'single', null, null);
values ('91d21eed-d2d4-5e39-bbf6-62a39177ea4b', '["t2"]'::jsonb, 'Since 2020 connects the past to now: has worked.', 'Since 2020 nối quá khứ với hiện tại: has worked.', null, null, 'She has worked here since 2020.');
values ('dc4da5ee-39fd-5dfc-9777-40e048f419d6', '28021070-9997-5d20-a09d-95c6a0706792', null, 4, 'sentence_transformation', 'Rewrite the sentence using the word in brackets.', null);
values ('0e43bc3c-a209-50a8-8d1a-ebf88b7c5939', '28021070-9997-5d20-a09d-95c6a0706792', 'dc4da5ee-39fd-5dfc-9777-40e048f419d6', 1, 8, 'I started learning English five years ago. (for)', null, 'text', null, null);
values ('0e43bc3c-a209-50a8-8d1a-ebf88b7c5939', '["I have been learning English for five years.","I have learned English for five years.","I have learnt English for five years.","I''ve been learning English for five years.","I''ve learned English for five years.","I''ve learnt English for five years."]'::jsonb, 'Started five years ago and still learning: present perfect with for.', 'Bắt đầu từ 5 năm trước và vẫn đang học: hiện tại hoàn thành với for.', null, null, null);
values ('d5cc9b6d-b272-5029-a6f0-21702e2c02a7', 2, '{"introEn":"Both tenses talk about the past, so they are easy to mix up. The secret question is: is the time finished, or does it still connect to now?","introVi":"Cả hai thì đều nói về quá khứ nên rất dễ nhầm. Câu hỏi bí mật là: khoảng thời gian đó đã kết thúc chưa, hay vẫn còn nối với hiện tại?","sections":[{"heading":"Past simple: the story is finished","bodyEn":"Use the past simple for actions at a finished time. We usually say or know when: yesterday, last year, in 2015, two days ago.","bodyVi":"Dùng quá khứ đơn cho hành động ở một thời điểm đã kết thúc. Thường ta nói rõ hoặc ai cũng biết là khi nào: yesterday, last year, in 2015, two days ago.","examples":[{"en":"I visited Da Lat last summer.","vi":"Tôi đi Đà Lạt hè năm ngoái."},{"en":"She graduated in 2020.","vi":"Cô ấy tốt nghiệp năm 2020."}]},{"heading":"Present perfect: past action, present connection","bodyEn":"Use the present perfect when the time is not finished or not important: experiences (ever, never), time up to now (since, for, so far) and past actions with a result now.","bodyVi":"Dùng hiện tại hoàn thành khi thời gian chưa kết thúc hoặc không quan trọng: trải nghiệm (ever, never), khoảng thời gian tới bây giờ (since, for, so far) và hành động quá khứ có kết quả ở hiện tại.","examples":[{"en":"Have you ever tried durian?","vi":"Bạn đã bao giờ ăn sầu riêng chưa?","note":"Experience: when is not important."},{"en":"I have lived here since 2018.","vi":"Tôi sống ở đây từ năm 2018.","note":"I still live here."},{"en":"I''ve lost my keys!","vi":"Tôi làm mất chìa khoá rồi!","note":"Result now: I can''t get in."}]},{"heading":"Let the time words decide","bodyEn":"Ago, last, yesterday and \"when\" questions point to the past simple. Since, already, yet, ever and so far point to the present perfect.","bodyVi":"Ago, last, yesterday và câu hỏi \"when\" kéo về quá khứ đơn. Since, already, yet, ever và so far kéo về hiện tại hoàn thành. Hãy để \"từ chỉ thời gian\" làm trọng tài.","examples":[{"en":"When did you start learning English?","vi":"Bạn bắt đầu học tiếng Anh khi nào?"},{"en":"I haven''t finished my essay yet.","vi":"Tôi vẫn chưa viết xong bài luận."}]}],"commonMistakes":[{"wrong":"I have visited Hue last year.","right":"I visited Hue last year.","whyEn":"Last year is a finished time, so use the past simple.","whyVi":"Last year là thời gian đã kết thúc, nên dùng quá khứ đơn."},{"wrong":"I live here since 2018.","right":"I have lived here since 2018.","whyEn":"Since connects the past to now, so use the present perfect.","whyVi":"Since nối quá khứ với hiện tại, nên dùng hiện tại hoàn thành. Tiếng Việt chỉ nói \"sống ở đây từ 2018\" nên ta hay quên."},{"wrong":"Did you ever try durian?","right":"Have you ever tried durian?","whyEn":"Asking about life experience uses the present perfect in British English.","whyVi":"Hỏi về trải nghiệm trong đời dùng hiện tại hoàn thành (theo tiếng Anh–Anh)."}],"ieltsTipEn":"In Writing Task 1, a graph about 2000–2020 is finished time: use the past simple. In Task 2, \"In recent years, online learning has grown\" uses the present perfect because the trend continues.","ieltsTipVi":"Trong Writing Task 1, biểu đồ 2000–2020 là thời gian đã kết thúc: dùng quá khứ đơn. Trong Task 2, \"In recent years, online learning has grown\" dùng hiện tại hoàn thành vì xu hướng vẫn tiếp diễn."}'::jsonb, '28021070-9997-5d20-a09d-95c6a0706792');

-- grammar topic relative-clauses (published, v1)
values ('c755ce0e-34f8-548a-8355-ef5825b71bc1', 'grammar_topic', 'relative-clauses', 'Relative clauses: who, which, that, whose, where', 'Join short sentences into smooth, longer ones without losing the reader.', 'B2', array[]::text[], 'ai_assisted', 'published', 1);
-- relative-clauses-practice (published, v1)
values ('75b89bf5-2369-5823-94a1-0ecb3d59f8f5', 'practice_set', 'relative-clauses-practice', 'Relative clauses: who, which, that, whose, where — practice', null, 'B2', array[]::text[], 'ai_assisted', 'published', 1);
values ('75b89bf5-2369-5823-94a1-0ecb3d59f8f5', 'grammar', 'practice', null);
values ('5862863f-7868-5aa9-9676-681ed772a357', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', null, 1, 'multiple_choice', 'Choose the correct option.', null);
values ('2fbf6c45-3b7e-5748-b45f-e73bb9959cb4', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', '5862863f-7868-5aa9-9676-681ed772a357', 1, 1, 'The teacher ___ helped me most was Ms Lan.', '[{"id":"A","text":"which"},{"id":"B","text":"who"},{"id":"C","text":"whose"}]'::jsonb, 'single', null, null);
values ('2fbf6c45-3b7e-5748-b45f-e73bb9959cb4', '["B"]'::jsonb, 'A teacher is a person, so use who.', 'Giáo viên là người nên dùng who.', null, null, null);
values ('1d062edb-acb2-5949-89b0-a6e665ffb717', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', '5862863f-7868-5aa9-9676-681ed772a357', 2, 2, 'This is the village ___ my grandparents grew up.', '[{"id":"A","text":"which"},{"id":"B","text":"where"},{"id":"C","text":"who"}]'::jsonb, 'single', null, null);
values ('1d062edb-acb2-5949-89b0-a6e665ffb717', '["B"]'::jsonb, 'A place, followed by a full clause (my grandparents grew up): where.', 'Nơi chốn, theo sau là một mệnh đề đầy đủ (my grandparents grew up): dùng where.', null, null, null);
values ('26d464d3-45d9-5a6d-a8f8-f962c9893113', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', '5862863f-7868-5aa9-9676-681ed772a357', 3, 3, 'Children ___ parents read to them often enjoy books.', '[{"id":"A","text":"who"},{"id":"B","text":"whose"},{"id":"C","text":"which"}]'::jsonb, 'single', null, null);
values ('26d464d3-45d9-5a6d-a8f8-f962c9893113', '["B"]'::jsonb, 'The parents belong to the children: whose.', 'Bố mẹ "của" các em nhỏ: dùng whose.', null, null, null);
values ('aeff1bcb-a56d-56de-8eb6-09a63d975149', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', null, 2, 'gap_fill', 'Write who, which, whose or where.', null);
values ('e99c703e-028c-5611-9213-432e0b6943cd', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', 'aeff1bcb-a56d-56de-8eb6-09a63d975149', 1, 4, 'Smartphones, ___ were rare twenty years ago, are now everywhere.', null, 'text', null, 1);
values ('e99c703e-028c-5611-9213-432e0b6943cd', '["which"]'::jsonb, 'Extra information about things, between commas: which (never that).', 'Thông tin phụ về đồ vật, nằm giữa hai dấu phẩy: which (không dùng that).', null, null, null);
values ('f466bfc0-8c29-59ca-9e03-1c404b3e003d', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', 'aeff1bcb-a56d-56de-8eb6-09a63d975149', 2, 5, 'Da Nang is a city ___ many tourists go for the beaches.', null, 'text', null, 1);
values ('f466bfc0-8c29-59ca-9e03-1c404b3e003d', '["where"]'::jsonb, 'A place, followed by a subject and verb (many tourists go): where.', 'Nơi chốn, theo sau là chủ ngữ và động từ (many tourists go): where.', null, null, null);
values ('0c2e2c34-bca6-587c-a1d2-e4b2eb71f91d', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', null, 3, 'error_correction', 'Spot the mistake: tap the word that is wrong.', null);
values ('ead2a957-ffa3-5c2f-a113-6c719d94d60a', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', '0c2e2c34-bca6-587c-a1d2-e4b2eb71f91d', 1, 6, 'The girl which won the prize is my cousin.', '[{"id":"t1","text":"The"},{"id":"t2","text":"girl"},{"id":"t3","text":"which"},{"id":"t4","text":"won"},{"id":"t5","text":"the"},{"id":"t6","text":"prize"},{"id":"t7","text":"is"},{"id":"t8","text":"my"},{"id":"t9","text":"cousin."}]'::jsonb, 'single', null, null);
values ('ead2a957-ffa3-5c2f-a113-6c719d94d60a', '["t3"]'::jsonb, 'The girl is a person: who.', 'Cô bé là người: dùng who.', null, null, 'The girl who won the prize is my cousin.');
values ('4c289d7b-5e10-59c3-9a4d-bb38acda4072', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', '0c2e2c34-bca6-587c-a1d2-e4b2eb71f91d', 2, 7, 'My laptop, that I bought last year, is already slow.', '[{"id":"t1","text":"My"},{"id":"t2","text":"laptop,"},{"id":"t3","text":"that"},{"id":"t4","text":"I"},{"id":"t5","text":"bought"},{"id":"t6","text":"last"},{"id":"t7","text":"year,"},{"id":"t8","text":"is"},{"id":"t9","text":"already"},{"id":"t10","text":"slow."}]'::jsonb, 'single', null, null);
values ('4c289d7b-5e10-59c3-9a4d-bb38acda4072', '["t3"]'::jsonb, 'Between commas, use which, not that.', 'Giữa hai dấu phẩy thì dùng which, không dùng that.', null, null, 'My laptop, which I bought last year, is already slow.');
values ('94b0258c-73aa-54ba-9c00-c619dfb0c7a9', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', null, 4, 'sentence_transformation', 'Join the sentences using the word in brackets.', null);
values ('69eece6c-5703-5e7e-8f39-e5b20e1b8289', '75b89bf5-2369-5823-94a1-0ecb3d59f8f5', '94b0258c-73aa-54ba-9c00-c619dfb0c7a9', 1, 8, 'I have a friend. Her brother is a famous singer. (whose)', null, 'text', null, null);
values ('69eece6c-5703-5e7e-8f39-e5b20e1b8289', '["I have a friend whose brother is a famous singer."]'::jsonb, 'Her brother belongs to my friend, so whose replaces her.', 'Anh trai là "của" người bạn, nên whose thay cho her.', null, null, null);
values ('c755ce0e-34f8-548a-8355-ef5825b71bc1', 4, '{"introEn":"Relative clauses join two ideas into one sentence. Examiners love them because they show range, as long as you pick the right little word.","introVi":"Mệnh đề quan hệ ghép hai ý thành một câu. Giám khảo rất thích vì chúng thể hiện sự đa dạng ngữ pháp, miễn là bạn chọn đúng \"từ nối\" nhỏ xíu.","sections":[{"heading":"Who for people, which for things, that for both","bodyEn":"Use who for people and which for things. In defining clauses, that can replace both.","bodyVi":"Who cho người, which cho vật. Trong mệnh đề xác định, that thay được cả hai.","examples":[{"en":"The teacher who helped me most was Ms Lan.","vi":"Giáo viên giúp tôi nhiều nhất là cô Lan."},{"en":"The phone that I bought last month is already broken.","vi":"Chiếc điện thoại tôi mua tháng trước đã hỏng rồi."}]},{"heading":"Commas or no commas?","bodyEn":"If the clause tells us which one, use no commas. If it only adds extra information, put it between commas and never use that.","bodyVi":"Nếu mệnh đề cho biết \"cái nào\" thì không có dấu phẩy. Nếu chỉ thêm thông tin phụ thì đặt giữa hai dấu phẩy, và không bao giờ dùng that.","examples":[{"en":"Students who skip breakfast find it hard to concentrate.","vi":"Học sinh bỏ bữa sáng thì khó tập trung.","note":"Which students? Those who skip breakfast."},{"en":"Hanoi, which is the capital, has terrible traffic.","vi":"Hà Nội, thủ đô, có giao thông rất tệ.","note":"Extra information: we already know which city."}]},{"heading":"Whose and where","bodyEn":"Whose shows that something belongs to someone. Where is for places, followed by a subject and a verb.","bodyVi":"Whose chỉ sự sở hữu. Where dùng cho nơi chốn, theo sau là chủ ngữ và động từ.","examples":[{"en":"I have a friend whose father is a pilot.","vi":"Tôi có một người bạn có bố là phi công."},{"en":"This is the café where we first met.","vi":"Đây là quán cà phê nơi chúng tôi gặp nhau lần đầu."}]}],"commonMistakes":[{"wrong":"The man which lives next door is a doctor.","right":"The man who lives next door is a doctor.","whyEn":"Use who for people.","whyVi":"Người thì dùng who. Hàng xóm của bạn không phải đồ vật đâu!"},{"wrong":"Hanoi, that is the capital, is very busy.","right":"Hanoi, which is the capital, is very busy.","whyEn":"That cannot be used in a clause between commas.","whyVi":"Mệnh đề nằm giữa hai dấu phẩy không dùng that."},{"wrong":"The city where I visited was beautiful.","right":"The city that I visited was beautiful.","whyEn":"Visit needs an object, so use that or which, not where.","whyVi":"Visit cần tân ngữ (visit somewhere), nên dùng that/which chứ không dùng where."}],"ieltsTipEn":"In Writing Task 2, combine two short sentences with a relative clause to improve flow: \"Many students work part-time. This affects their studies.\" becomes \"Many students work part-time, which affects their studies.\"","ieltsTipVi":"Trong Writing Task 2, hãy gộp hai câu ngắn bằng mệnh đề quan hệ để bài mượt hơn: \"Many students work part-time. This affects their studies.\" thành \"Many students work part-time, which affects their studies.\""}'::jsonb, '75b89bf5-2369-5823-94a1-0ecb3d59f8f5');





















commit;
